package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"log"
	"os"
	"strings"
)

const VERSION = "0.32.0"

func main() {
	// Set up logging format
	log.SetFlags(0)
	log.SetOutput(os.Stderr)

	config, err := parseArgs()
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n\nFor more information, try '--help'.\n", err)
		os.Exit(1)
	}

	if config.PrintCompletions != "" {
		printCompletions(config.PrintCompletions)
		return
	}

	if config.PrintManpage {
		printManpage()
		return
	}

	// Generate random route if requested
	if config.RandomRoute {
		b := make([]byte, 3)
		rand.Read(b)
		config.RoutePrefix = "/" + hex.EncodeToString(b)
	}

	// Handle case where path is not specified
	if config.Path == "" {
		// Check if stdin is a terminal
		if !isTerminal() {
			timestamp := logTimestamp()
			fmt.Fprintf(os.Stderr, "%s [ERROR] Refusing to start as no explicit serve path was set and no interactive terminal was attached\n", timestamp)
			fmt.Fprintf(os.Stderr, "%s [ERROR] Please set an explicit serve path like: `miniserve /my/path`\n", timestamp)
			fmt.Fprintf(os.Stderr, "Error: Refusing to start as no explicit serve path was set and no interactive terminal was attached\nPlease set an explicit serve path like: `miniserve /my/path`\n")
			os.Exit(1)
		}
		// Use current directory
		cwd, err := os.Getwd()
		if err != nil {
			log.Fatal(err)
		}
		config.Path = cwd
	}

	// Resolve the path
	absPath, err := resolvePath(config.Path)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
	config.Path = absPath

	// Start the server
	if err := runServer(config); err != nil {
		timestamp := logTimestamp()
		// Parse the error to match original format
		errStr := err.Error()
		if strings.Contains(errStr, "address already in use") || strings.Contains(errStr, "bind:") {
			bindAddr := getBindAddr(config)
			fmt.Fprintf(os.Stderr, "%s [ERROR] Failed to bind server to %s\n", timestamp, bindAddr)
			fmt.Fprintf(os.Stderr, "%s [ERROR] caused by: Address already in use (os error 98)\n", timestamp)
			fmt.Fprintf(os.Stderr, "Error: Failed to bind server to %s\ncaused by: Address already in use (os error 98)\n", bindAddr)
		} else {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		}
		os.Exit(1)
	}
}

func getBindAddr(config *Config) string {
	return fmt.Sprintf("[::]:%d", config.Port)
}

func logTimestamp() string {
	now := time.Now().UTC()
	return now.Format("Mon, 02 Jan 2006 15:04:05 +0000")
}

func isTerminal() bool {
	fi, err := os.Stdin.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

func resolvePath(p string) (string, error) {
	abs, err := filepath.Abs(p)
	if err != nil {
		return "", err
	}
	_, err = os.Stat(abs)
	if err != nil {
		return "", fmt.Errorf("path %q does not exist", p)
	}
	return abs, nil
}
GOEOF

