package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"os"
	"path/filepath"
	"syscall"
	"time"
)

const VERSION = "0.32.0"

func main() {
	config, err := parseArgs(os.Args[1:])
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n\nFor more information, try '--help'.\n", err)
		os.Exit(2)
	}

	if config.PrintCompletions != "" {
		printCompletions(config.PrintCompletions)
		return
	}

	if config.PrintManpage {
		printManpage()
		return
	}

	// Handle path
	if config.Path == "" {
		if !isTerminal() {
			ts := logTimestamp()
			fmt.Fprintf(os.Stderr, "%s [ERROR] Refusing to start as no explicit serve path was set and no interactive terminal was attached\n", ts)
			fmt.Fprintf(os.Stderr, "%s [ERROR] Please set an explicit serve path like: `miniserve /my/path`\n", ts)
			fmt.Fprintln(os.Stderr, "Error: Refusing to start as no explicit serve path was set and no interactive terminal was attached\nPlease set an explicit serve path like: `miniserve /my/path`")
			os.Exit(1)
		}
		cwd, err := os.Getwd()
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
		config.Path = cwd
	}

	// Resolve path
	absPath, err := filepath.Abs(config.Path)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
	config.Path = absPath

	// Generate random route if requested
	if config.RandomRoute {
		b := make([]byte, 3)
		rand.Read(b)
		config.RoutePrefix = "/" + hex.EncodeToString(b)
	}

	// Start the server
	if err := runServer(config); err != nil {
		os.Exit(1)
	}
}

func logTimestamp() string {
	return time.Now().UTC().Format("Mon, 02 Jan 2006 15:04:05 +0000")
}

func isTerminal() bool {
	var t syscall.Termios
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL,
		uintptr(syscall.Stdin),
		syscall.TCGETS,
		uintptr(unsafe.Pointer(&t)))
	return errno == 0
}
GOEOF
