func parseArgs(args []string) (*Config, error) {
	config := defaultConfig()

	i := 0
	for i < len(args) {
		arg := args[i]

		if arg == "--" {
			i++
			// Rest are positional args (path)
			if i < len(args) {
				config.Path = args[i]
			}
			break
		}

		if !strings.HasPrefix(arg, "-") {
			// Positional argument - the path
			config.Path = arg
			i++
			continue
		}

		// Handle --flag=value format
		var flagName, flagValue string
		hasValue := false
		if idx := strings.IndexByte(arg[1:], '='); idx >= 0 && arg[0] == '-' && arg[1] == '-' {
			flagName = arg[:idx+2]
			flagValue = arg[idx+3:]
			hasValue = true
		} else {
			flagName = arg
		}

		switch flagName {
		case "-v", "--verbose":
			config.Verbose = true
		case "--spa":
			config.SPA = true
		case "--pretty-urls":
			config.PrettyURLs = true
		case "-P", "--no-symlinks":
			config.NoSymlinks = true
