		case "--hide-theme-selector":
			config.HideThemeSelector = true
		case "-W", "--show-wget-footer":
			config.ShowWgetFooter = true
		case "--random-route":
			config.RandomRoute = true
		case "--readme":
			config.Readme = true
		case "-I", "--disable-indexing":
			config.DisableIndexing = true
		case "--enable-webdav":
			config.EnableWebDav = true
		case "--print-manpage":
			config.PrintManpage = true
		case "--chmod":
			config.ChmodEnabled = true
		case "--directory-size":
			config.DirectorySizeEnabled = true
		case "-h", "--help":
			printHelp()
			os.Exit(0)
		case "-V", "--version":
			fmt.Printf("miniserve %s\n", VERSION)
			os.Exit(0)

		// Options with values
		case "-p", "--port":
			v, err := getNextArg(args, &i, hasValue, flagValue)
			if err != nil { return nil, err }
			if _, err := fmt.Sscanf(v, "%d", &config.Port); err != nil {
				return nil, fmt.Errorf("invalid port value: %s", v)
			}
		case "-i", "--interfaces":
			v, err := getNextArg(args, &i, hasValue, flagValue)
			if err != nil { return nil, err }
			config.Interfaces = append(config.Interfaces, v)
		case "-a", "--auth":
			v, err := getNextArg(args, &i, hasValue, flagValue)
			if err != nil { return nil, err }
			entry, err := parseAuthEntry(v)
			if err != nil { return nil, err }
			config.Auth = append(config.Auth, entry)
		case "--auth-file":
			v, err := getNextArg(args, &i, hasValue, flagValue)
			if err != nil { return nil, err }
			config.AuthFile = v
		case "--route-prefix":
			v, err := getNextArg(args, &i, hasValue, flagValue)
			if err != nil { return nil, err }
