package main

import (
	"fmt"
	"math"
	"time"
)

// humanizeSize formats a file size in human-readable format
func humanizeSize(size int64) string {
	if size == 0 {
		return "0 B"
	}

	const unit = 1024
	if size < unit {
		return fmt.Sprintf("%d B", size)
	}

	div := int64(unit)
	exp := 0
	n := size / unit
	for n >= unit {
		div *= unit
		exp++
		n /= unit
	}

	f := float64(size) / float64(div)
	units := []string{"KiB", "MiB", "GiB", "TiB", "PiB", "EiB"}

	// Format with 1 decimal place
	return fmt.Sprintf("%.1f %s", f, units[exp])
}

// humanizeTime formats a time in relative human-readable format
// Based on chrono-humanize crate behavior
func humanizeTime(t time.Time) string {
	now := time.Now()
	diff := now.Sub(t)

	if diff < 0 {
		// Future time
		absDiff := -diff
		return formatPositiveDuration(absDiff, "from now")
	}

	return formatPositiveDuration(diff, "ago")
}

func formatPositiveDuration(d time.Duration, suffix string) string {
	seconds := int64(d.Seconds())

	if seconds <= 1 {
		return "now"
	}

	minutes := int64(math.Round(float64(seconds) / 60.0))
	hours := int64(math.Round(float64(seconds) / 3600.0))
	days := int64(math.Round(float64(seconds) / 86400.0))
	weeks := int64(math.Round(float64(seconds) / (7 * 86400.0)))
	months := int64(math.Round(float64(seconds) / (30 * 86400.0)))
	years := int64(math.Round(float64(seconds) / (365 * 86400.0)))

	switch {
	case seconds < 45:
		return fmt.Sprintf("%d seconds %s", seconds, suffix)
	case seconds < 90:
		return "a minute " + suffix
	case minutes < 45:
		return fmt.Sprintf("%d minutes %s", minutes, suffix)
	case minutes < 90:
		return "an hour " + suffix
	case hours < 22:
		return fmt.Sprintf("%d hours %s", hours, suffix)
	case hours < 36:
		return "a day " + suffix
	case days < 26:
		return fmt.Sprintf("%d days %s", days, suffix)
	case days < 45:
		return "a month " + suffix
	case days < 345:
		return fmt.Sprintf("%d months %s", months, suffix)
	case days < 545:
		return "a year " + suffix
	default:
		return fmt.Sprintf("%d years %s", years, suffix)
	}
}

// formatDatetime formats a file modification time in the format used by miniserve
func formatDatetime(t time.Time) string {
	utc := t.UTC()
	return utc.Format("2006-01-02 15:04:05 +00:00 ")
}

// percentEncode encodes a path segment for use in URLs
func percentEncode(s string) string {
	var result []byte
	for i := 0; i < len(s); {
		c := s[i]
		if isUnreserved(c) {
			result = append(result, c)
			i++
		} else {
			result = append(result, fmt.Sprintf("%%%02X", c)...)
			i++
		}
	}
	return string(result)
}

func isUnreserved(c byte) bool {
	return (c >= 'A' && c <= 'Z') ||
		(c >= 'a' && c <= 'z') ||
		(c >= '0' && c <= '9') ||
		c == '-' || c == '_' || c == '.' || c == '~'
}

// escapeHTML escapes HTML special characters
func escapeHTML(s string) string {
	var result []byte
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '&':
			result = append(result, '&', 'a', 'm', 'p', ';')
		case '<':
			result = append(result, '&', 'l', 't', ';')
		case '>':
			result = append(result, '&', 'g', 't', ';')
		case '"':
			result = append(result, '&', 'q', 'u', 'o', 't', ';')
		case '\'':
			result = append(result, '&', '#', '3', '9', ';')
		default:
			result = append(result, s[i])
		}
	}
	return string(result)
}
