// humanizeSize formats a file size in human-readable binary format (KiB, MiB, etc.)
func humanizeSize(size int64) string {
	if size == 0 {
		return "0 B"
	}
	if size < 1024 {
		return fmt.Sprintf("%d B", size)
	}

	f := float64(size)
	units := []string{"KiB", "MiB", "GiB", "TiB", "PiB", "EiB"}
	idx := 0

	for f >= 1024.0 && idx < len(units)-1 {
		f /= 1024.0
		idx++
	}

	return fmt.Sprintf("%.1f %s", f, units[idx])
}

// humanizeTime formats a time relative to now
func humanizeTime(t time.Time) string {
	now := time.Now()
	elapsed := now.Sub(t)

	if elapsed < 0 {
		return "in the future"
	}

	s := int64(elapsed.Seconds()) // floor to integer seconds

	if s <= 10 {
		return "now"
	}
	if s <= 45 {
		return fmt.Sprintf("%d seconds ago", s)
	}
	if s <= 90 {
