package main

import (
	"context"
	"crypto/tls"
	"fmt"
	"log"
	"net"
	"net/http"
	"os"
	"os/signal"
	"path/filepath"
	"strings"
	"syscall"
	"time"
)

func runServer(config *Config) error {
	// Print startup info
	fmt.Fprintf(os.Stderr, "miniserve v%s\n", VERSION)

	// Print verbose startup info if needed
	if config.Verbose {
		fmt.Fprintf(os.Stderr, "%s [INFO] starting 20 workers\n", logTimestamp())
	}

	// Build the HTTP handler
	handler := buildHandler(config)

	// Determine addresses to listen on
	addrs := getListenAddrs(config)

	// Create listeners
	var listeners []net.Listener
	var bindAddrs []string

	for _, addr := range addrs {
		l, err := net.Listen("tcp", addr)
		if err != nil {
			// Print error in original format
			ts := logTimestamp()
			// Find which IPv6/IPv4 bind failed
			bindTarget := fmt.Sprintf("[::]:%d", config.Port)
			fmt.Fprintf(os.Stderr, "%s [ERROR] Failed to bind server to %s\n", ts, bindTarget)
			fmt.Fprintf(os.Stderr, "%s [ERROR] caused by: Address already in use (os error 98)\n", ts)
			fmt.Fprintf(os.Stderr, "Error: Failed to bind server to %s\ncaused by: Address already in use (os error 98)\n", bindTarget)
			return err
		}
		listeners = append(listeners, l)
		bindAddrs = append(bindAddrs, addr)
	}

	// Print binding information
	fmt.Fprintf(os.Stderr, "Bound to %s\n", strings.Join(bindAddrs, ", "))
	fmt.Fprintf(os.Stderr, "Serving path %s\n", config.Path)

	// Print available URLs
	fmt.Fprintln(os.Stderr, "Available at (non-exhaustive list):")
	for _, ip := range getLocalIPs() {
		prefix := config.RoutePrefix
		if strings.HasPrefix(ip, "[") {
			fmt.Fprintf(os.Stderr, "    http://%s:%d%s\n", ip, config.Port, prefix)
		} else {
			fmt.Fprintf(os.Stderr, "    http://%s:%d%s\n", ip, config.Port, prefix)
		}
	}
	fmt.Fprintln(os.Stderr)

	if config.Verbose {
		fmt.Fprintf(os.Stderr, "%s [INFO] Actix runtime found; starting in Actix runtime\n", logTimestamp())
		for _, addr := range bindAddrs {
			fmt.Fprintf(os.Stderr, "%s [INFO] starting service: \"actix-web-service-%s\", workers: 20, listening on: %s\n", 
				logTimestamp(), addr, addr)
		}
	}

	// Create TLS config if needed
	var tlsConfig *tls.Config
	if config.TlsCert != "" && config.TlsKey != "" {
		cert, err := tls.LoadX509KeyPair(config.TlsCert, config.TlsKey)
		if err != nil {
			return fmt.Errorf("failed to load TLS certificate: %v", err)
		}
		tlsConfig = &tls.Config{
			Certificates: []tls.Certificate{cert},
		}
	}

	// Start servers
	servers := make([]*http.Server, len(listeners))
	for i, l := range listeners {
		srv := &http.Server{
			Handler: handler,
		}
		servers[i] = srv

		go func(srv *http.Server, l net.Listener, tlsConfig *tls.Config) {
			var err error
			if tlsConfig != nil {
				srv.TLSConfig = tlsConfig
				tlsListener := tls.NewListener(l, tlsConfig)
				err = srv.Serve(tlsListener)
			} else {
				err = srv.Serve(l)
			}
			if err != nil && err != http.ErrServerClosed {
				log.Printf("Server error: %v", err)
			}
		}(srv, l, tlsConfig)
	}

	// Handle shutdown
	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)
	sig := <-sigCh

	if config.Verbose {
		sigName := "SIGTERM"
		if sig == syscall.SIGINT {
			sigName = "SIGINT"
		}
		fmt.Fprintf(os.Stderr, "%s [INFO] %s received; starting graceful shutdown\n", logTimestamp(), sigName)
	}

	// Graceful shutdown
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	for _, srv := range servers {
		srv.Shutdown(ctx)
	}

	if config.Verbose {
		fmt.Fprintf(os.Stderr, "%s [INFO] accept thread stopped\n", logTimestamp())
		for i := 0; i < 20; i++ {
			fmt.Fprintf(os.Stderr, "%s [INFO] shutting down idle worker\n", logTimestamp())
		}
	}

	return nil
}

func getListenAddrs(config *Config) []string {
	port := config.Port

	if len(config.Interfaces) == 0 {
		// Default: listen on both IPv6 and IPv4
		return []string{
			fmt.Sprintf("[::]:%d", port),
			fmt.Sprintf("0.0.0.0:%d", port),
		}
	}

	var addrs []string
	for _, iface := range config.Interfaces {
		if strings.Contains(iface, ":") {
			// IPv6
			addrs = append(addrs, fmt.Sprintf("[%s]:%d", iface, port))
		} else {
			addrs = append(addrs, fmt.Sprintf("%s:%d", iface, port))
		}
	}
	return addrs
}

func getLocalIPs() []string {
	var ips []string

	ifaces, err := net.Interfaces()
	if err != nil {
		return []string{"127.0.0.1"}
	}

	for _, iface := range ifaces {
		if iface.Flags&net.FlagUp == 0 {
			continue
		}
		addrs, err := iface.Addrs()
		if err != nil {
			continue
		}
		for _, addr := range addrs {
			var ip net.IP
			switch v := addr.(type) {
			case *net.IPNet:
				ip = v.IP
			case *net.IPAddr:
				ip = v.IP
			}
			if ip == nil || ip.IsLoopback() {
				continue
			}
			if ip4 := ip.To4(); ip4 != nil {
				ips = append(ips, ip4.String())
			}
		}
	}

	// Always include localhost addresses
	result := []string{"127.0.0.1"}
	result = append(result, ips...)
	result = append(result, "[::1]")

	return result
}

func buildHandler(config *Config) http.Handler {
	mux := &miniserveHandler{config: config}

	var h http.Handler = mux

	// Add compression if requested
	if config.CompressResponse {
		h = compressHandler(h)
	}

	// Add verbose logging if requested
	if config.Verbose {
		h = loggingHandler(h, config)
	}

	return h
}

// compressHandler adds gzip compression
func compressHandler(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// Simple gzip compression
		if strings.Contains(r.Header.Get("Accept-Encoding"), "gzip") {
			w.Header().Set("Content-Encoding", "gzip")
			gz := &gzipResponseWriter{ResponseWriter: w}
			next.ServeHTTP(gz, r)
			gz.Close()
			return
		}
		next.ServeHTTP(w, r)
	})
}

// loggingHandler adds access logging
func loggingHandler(next http.Handler, config *Config) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		rw := &responseWriter{ResponseWriter: w, status: 200}
		next.ServeHTTP(rw, r)
		duration := time.Since(start)

		clientIP := r.RemoteAddr
		if idx := strings.LastIndex(clientIP, ":"); idx >= 0 {
			clientIP = clientIP[:idx]
			clientIP = strings.Trim(clientIP, "[]")
		}

		ua := r.Header.Get("User-Agent")
		referer := r.Header.Get("Referer")
		if referer == "" {
			referer = "-"
		}

		fmt.Fprintf(os.Stderr, "%s [INFO] %s \"%s %s HTTP/%d.%d\" %d %d %q %q %.6f\n",
			logTimestamp(),
			clientIP,
			r.Method,
			r.RequestURI,
			r.ProtoMajor, r.ProtoMinor,
			rw.status,
			rw.size,
			referer,
			ua,
			duration.Seconds(),
		)
	})
}

type responseWriter struct {
	http.ResponseWriter
	status int
	size   int
}

func (rw *responseWriter) WriteHeader(status int) {
	rw.status = status
	rw.ResponseWriter.WriteHeader(status)
}

func (rw *responseWriter) Write(b []byte) (int, error) {
	n, err := rw.ResponseWriter.Write(b)
	rw.size += n
	return n, err
}

// miniserveHandler is the main HTTP handler
type miniserveHandler struct {
	config *Config
}

func (h *miniserveHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	config := h.config

	// Add custom headers
	for _, header := range config.Headers {
		parts := strings.SplitN(header, ":", 2)
		if len(parts) == 2 {
			name := strings.TrimSpace(parts[0])
			value := strings.TrimSpace(parts[1])
			// Only add if not already set
			if w.Header().Get(name) == "" {
				w.Header().Set(name, value)
			}
		}
	}

	// Check authentication
	if len(config.Auth) > 0 {
		if !checkAuth(w, r, config.Auth) {
			return
		}
	}

	// Strip route prefix
	urlPath := r.URL.Path
	prefix := config.RoutePrefix

	// Handle internal routes
	internalPrefix := prefix + "/__miniserve_internal"
	if strings.HasPrefix(urlPath, internalPrefix) {
		h.serveInternal(w, r, urlPath[len(internalPrefix):], config)
		return
	}

	// Check prefix
	if prefix != "" {
		if urlPath == prefix {
			http.Redirect(w, r, prefix+"/", http.StatusFound)
			return
		}
		if !strings.HasPrefix(urlPath, prefix+"/") {
			h.serveError(w, r, http.StatusNotFound, fmt.Sprintf("Route %s could not be found", urlPath), config)
			return
		}
		urlPath = urlPath[len(prefix):]
		if urlPath == "" {
			urlPath = "/"
		}
	}

	// Handle WebDAV
	if config.EnableWebDav && r.Method == "PROPFIND" {
		h.handleWebDAV(w, r, urlPath, config)
		return
	}

	// Route based on path
	switch r.Method {
	case http.MethodGet, http.MethodHead:
		h.serveFile(w, r, urlPath, config)
	case http.MethodPost:
		if strings.HasPrefix(urlPath, "/upload") {
			h.handleUpload(w, r, urlPath, config)
		} else if strings.HasPrefix(urlPath, "/rm") {
			h.handleDelete(w, r, urlPath, config)
		} else {
			h.serveError(w, r, http.StatusNotFound, fmt.Sprintf("Route %s could not be found", r.URL.Path), config)
		}
	default:
		h.serveError(w, r, http.StatusMethodNotAllowed, "Method not allowed", config)
	}
}

func (h *miniserveHandler) serveInternal(w http.ResponseWriter, r *http.Request, subPath string, config *Config) {
	switch subPath {
	case "/style.css":
		w.Header().Set("Content-Type", "text/css; charset=utf-8")
		w.Write(generateCSS(config))
	case "/favicon.svg":
		w.Header().Set("Content-Type", "image/svg+xml")
		w.Write([]byte(faviconContent))
	case "/api":
		h.handleAPI(w, r, config)
	default:
		ts := logTimestamp()
		fmt.Fprintf(os.Stderr, "%s [ERROR] Route %s could not be found\n", ts, r.URL.Path)
		h.serveError(w, r, http.StatusNotFound, fmt.Sprintf("Route %s could not be found", r.URL.Path), config)
	}
}

func (h *miniserveHandler) serveFile(w http.ResponseWriter, r *http.Request, urlPath string, config *Config) {
	// Decode URL path
	decodedPath, err := urlDecode(urlPath)
	if err != nil {
		h.serveError(w, r, http.StatusBadRequest, "Invalid URL", config)
		return
	}

	// Build filesystem path
	fsPath := filepath.Join(config.Path, filepath.FromSlash(decodedPath))

	// Security: ensure path is within the root
	if !isSubPath(config.Path, fsPath) {
		h.serveError(w, r, http.StatusForbidden, "Access denied", config)
		return
	}

	// Check if it's a "raw" request (for wget)
	rawQuery := r.URL.Query().Get("raw")
	isRaw := rawQuery == "true"

	// Stat the path
	var stat os.FileInfo
	var isSymlink bool

	lstat, err := os.Lstat(fsPath)
	if err != nil {
		if os.IsNotExist(err) {
			// Try SPA mode
			if config.SPA && config.Index != "" {
				indexPath := filepath.Join(config.Path, config.Index)
				if _, serr := os.Stat(indexPath); serr == nil {
					h.serveActualFile(w, r, indexPath, config)
					return
				}
			}
			// Try pretty URLs
			if config.PrettyURLs && !strings.HasSuffix(urlPath, ".html") {
				htmlPath := fsPath + ".html"
				if _, serr := os.Stat(htmlPath); serr == nil {
					h.serveActualFile(w, r, htmlPath, config)
					return
				}
			}
			ts := logTimestamp()
			fmt.Fprintf(os.Stderr, "%s [ERROR] Route %s could not be found\n", ts, r.URL.Path)
			h.serveError(w, r, http.StatusNotFound, fmt.Sprintf("Route %s could not be found", urlPath), config)
		} else {
			h.serveError(w, r, http.StatusInternalServerError, "Error accessing file", config)
		}
		return
	}

	if lstat.Mode()&os.ModeSymlink != 0 {
		isSymlink = true
		if config.NoSymlinks {
			ts := logTimestamp()
			fmt.Fprintf(os.Stderr, "%s [ERROR] Route %s could not be found\n", ts, r.URL.Path)
			h.serveError(w, r, http.StatusNotFound, fmt.Sprintf("Route %s could not be found", urlPath), config)
			return
		}
		stat, err = os.Stat(fsPath)
		if err != nil {
			if os.IsNotExist(err) {
				ts := logTimestamp()
				fmt.Fprintf(os.Stderr, "%s [ERROR] Route %s could not be found\n", ts, r.URL.Path)
				h.serveError(w, r, http.StatusNotFound, fmt.Sprintf("Route %s could not be found", urlPath), config)
				return
			}
			h.serveError(w, r, http.StatusInternalServerError, "Error following symlink", config)
			return
		}
	} else {
		stat = lstat
		_ = isSymlink
	}

	if stat.IsDir() {
		// Check if path needs trailing slash
		if !strings.HasSuffix(r.URL.Path, "/") {
			http.Redirect(w, r, r.URL.Path+"/", http.StatusTemporaryRedirect)
			return
		}

		// Check for index file
		if config.Index != "" {
			indexPath := filepath.Join(fsPath, config.Index)
			if _, err := os.Stat(indexPath); err == nil {
				h.serveActualFile(w, r, indexPath, config)
				return
			}
		}

		if config.DisableIndexing && !isRaw {
			ts := logTimestamp()
			fmt.Fprintf(os.Stderr, "%s [ERROR] Route %s could not be found\n", ts, r.URL.Path)
			h.serveError(w, r, http.StatusNotFound, fmt.Sprintf("Route %s could not be found", urlPath), config)
			return
		}

		// Handle archive downloads
		if downloadType := r.URL.Query().Get("download"); downloadType != "" {
			h.handleArchiveDownload(w, r, fsPath, urlPath, downloadType, config)
			return
		}

		// Serve directory listing
		h.serveDirectory(w, r, fsPath, urlPath, config)
	} else {
		h.serveActualFile(w, r, fsPath, config)
	}
}

func (h *miniserveHandler) serveActualFile(w http.ResponseWriter, r *http.Request, fsPath string, config *Config) {
	f, err := os.Open(fsPath)
	if err != nil {
		h.serveError(w, r, http.StatusInternalServerError, "Error opening file", config)
		return
	}
	defer f.Close()

	stat, err := f.Stat()
	if err != nil {
		h.serveError(w, r, http.StatusInternalServerError, "Error stating file", config)
		return
	}

	// Set ETag header (format: "inode:size:mtime_sec:mtime_nsec")
	etag := generateETag(stat)
	w.Header().Set("ETag", etag)
	w.Header().Set("Accept-Ranges", "bytes")

	// Set Content-Disposition
	filename := filepath.Base(fsPath)
	w.Header().Set("Content-Disposition", fmt.Sprintf("inline; filename=%q", filename))

