	rw.ResponseWriter.WriteHeader(status)
}

func (rw *responseWriter) Write(b []byte) (int, error) {
	n, err := rw.ResponseWriter.Write(b)
	rw.size += n
	return n, err
}

// miniserveHandler is the main HTTP handler
type miniserveHandler struct {
	config *Config
}

func (h *miniserveHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	config := h.config

	// Add custom headers
	for _, header := range config.Headers {
		parts := strings.SplitN(header, ":", 2)
		if len(parts) == 2 {
			name := strings.TrimSpace(parts[0])
			value := strings.TrimSpace(parts[1])
			// Only add if not already set
			if w.Header().Get(name) == "" {
				w.Header().Set(name, value)
			}
		}
	}

	// Check authentication
	if len(config.Auth) > 0 {
		if !checkAuth(w, r, config.Auth) {
			return
		}
	}

	// Strip route prefix
	urlPath := r.URL.Path
	prefix := config.RoutePrefix

	// Handle internal routes
	internalPrefix := prefix + "/__miniserve_internal"
	if strings.HasPrefix(urlPath, internalPrefix) {
		h.serveInternal(w, r, urlPath[len(internalPrefix):], config)
		return
	}

	// Check prefix
	if prefix != "" {
		if urlPath == prefix {
			http.Redirect(w, r, prefix+"/", http.StatusFound)
			return
		}
		if !strings.HasPrefix(urlPath, prefix+"/") {
			h.serveError(w, r, http.StatusNotFound, fmt.Sprintf("Route %s could not be found", urlPath), config)
			return
		}
		urlPath = urlPath[len(prefix):]
		if urlPath == "" {
			urlPath = "/"
		}
	}

	// Handle WebDAV
	if config.EnableWebDav && r.Method == "PROPFIND" {
		h.handleWebDAV(w, r, urlPath, config)
		return
	}

	// Route based on path
	switch r.Method {
	case http.MethodGet, http.MethodHead:
		h.serveFile(w, r, urlPath, config)
	case http.MethodPost:
		if strings.HasPrefix(urlPath, "/upload") {
			h.handleUpload(w, r, urlPath, config)
		} else if strings.HasPrefix(urlPath, "/rm") {
			h.handleDelete(w, r, urlPath, config)
		} else {
			h.serveError(w, r, http.StatusNotFound, fmt.Sprintf("Route %s could not be found", r.URL.Path), config)
		}
	default:
		h.serveError(w, r, http.StatusMethodNotAllowed, "Method not allowed", config)
	}
}

func (h *miniserveHandler) serveInternal(w http.ResponseWriter, r *http.Request, subPath string, config *Config) {
	switch subPath {
	case "/style.css":
		w.Header().Set("Content-Type", "text/css; charset=utf-8")
		w.Write(generateCSS(config))
	case "/favicon.svg":
		w.Header().Set("Content-Type", "image/svg+xml")
		w.Write([]byte(faviconContent))
	case "/api":
		h.handleAPI(w, r, config)
	default:
		ts := logTimestamp()
		fmt.Fprintf(os.Stderr, "%s [ERROR] Route %s could not be found\n", ts, r.URL.Path)
		h.serveError(w, r, http.StatusNotFound, fmt.Sprintf("Route %s could not be found", r.URL.Path), config)
	}
}

func (h *miniserveHandler) serveFile(w http.ResponseWriter, r *http.Request, urlPath string, config *Config) {
	// Decode URL path
	decodedPath, err := urlDecode(urlPath)
	if err != nil {
		h.serveError(w, r, http.StatusBadRequest, "Invalid URL", config)
		return
	}

	// Build filesystem path
	fsPath := filepath.Join(config.Path, filepath.FromSlash(decodedPath))

	// Security: ensure path is within the root
	if !isSubPath(config.Path, fsPath) {
		h.serveError(w, r, http.StatusForbidden, "Access denied", config)
		return
	}

	// Check if it's a "raw" request (for wget)
	rawQuery := r.URL.Query().Get("raw")
	isRaw := rawQuery == "true"

	// Stat the path
	var stat os.FileInfo
	var isSymlink bool

	lstat, err := os.Lstat(fsPath)
	if err != nil {
		if os.IsNotExist(err) {
			// Try SPA mode
			if config.SPA && config.Index != "" {
				indexPath := filepath.Join(config.Path, config.Index)
				if _, serr := os.Stat(indexPath); serr == nil {
					h.serveActualFile(w, r, indexPath, config)
					return
				}
			}
			// Try pretty URLs
			if config.PrettyURLs && !strings.HasSuffix(urlPath, ".html") {
				htmlPath := fsPath + ".html"
				if _, serr := os.Stat(htmlPath); serr == nil {
					h.serveActualFile(w, r, htmlPath, config)
					return
				}
			}
			ts := logTimestamp()
			fmt.Fprintf(os.Stderr, "%s [ERROR] Route %s could not be found\n", ts, r.URL.Path)
			h.serveError(w, r, http.StatusNotFound, fmt.Sprintf("Route %s could not be found", urlPath), config)
		} else {
			h.serveError(w, r, http.StatusInternalServerError, "Error accessing file", config)
		}
		return
	}

	if lstat.Mode()&os.ModeSymlink != 0 {
		isSymlink = true
		if config.NoSymlinks {
			ts := logTimestamp()
			fmt.Fprintf(os.Stderr, "%s [ERROR] Route %s could not be found\n", ts, r.URL.Path)
			h.serveError(w, r, http.StatusNotFound, fmt.Sprintf("Route %s could not be found", urlPath), config)
			return
		}
		stat, err = os.Stat(fsPath)
		if err != nil {
			if os.IsNotExist(err) {
				ts := logTimestamp()
				fmt.Fprintf(os.Stderr, "%s [ERROR] Route %s could not be found\n", ts, r.URL.Path)
				h.serveError(w, r, http.StatusNotFound, fmt.Sprintf("Route %s could not be found", urlPath), config)
				return
			}
			h.serveError(w, r, http.StatusInternalServerError, "Error following symlink", config)
			return
		}
	} else {
		stat = lstat
		_ = isSymlink
	}

	if stat.IsDir() {
		// Check if path needs trailing slash
		if !strings.HasSuffix(r.URL.Path, "/") {
			http.Redirect(w, r, r.URL.Path+"/", http.StatusTemporaryRedirect)
			return
		}

		// Check for index file
		if config.Index != "" {
			indexPath := filepath.Join(fsPath, config.Index)
			if _, err := os.Stat(indexPath); err == nil {
				h.serveActualFile(w, r, indexPath, config)
				return
			}
		}

		if config.DisableIndexing && !isRaw {
			ts := logTimestamp()
			fmt.Fprintf(os.Stderr, "%s [ERROR] Route %s could not be found\n", ts, r.URL.Path)
			h.serveError(w, r, http.StatusNotFound, fmt.Sprintf("Route %s could not be found", urlPath), config)
			return
		}

		// Handle archive downloads
		if downloadType := r.URL.Query().Get("download"); downloadType != "" {
			h.handleArchiveDownload(w, r, fsPath, urlPath, downloadType, config)
			return
		}

		// Serve directory listing
		h.serveDirectory(w, r, fsPath, urlPath, config)
	} else {
		h.serveActualFile(w, r, fsPath, config)
	}
}

func (h *miniserveHandler) serveActualFile(w http.ResponseWriter, r *http.Request, fsPath string, config *Config) {
	f, err := os.Open(fsPath)
	if err != nil {
		h.serveError(w, r, http.StatusInternalServerError, "Error opening file", config)
		return
	}
	defer f.Close()

	stat, err := f.Stat()
	if err != nil {
		h.serveError(w, r, http.StatusInternalServerError, "Error stating file", config)
		return
	}

	// Set ETag header (format: "inode:size:mtime_sec:mtime_nsec")
	etag := generateETag(stat)
	w.Header().Set("ETag", etag)
	w.Header().Set("Accept-Ranges", "bytes")

	// Set Content-Disposition
	filename := filepath.Base(fsPath)
	w.Header().Set("Content-Disposition", fmt.Sprintf("inline; filename=%q", filename))

	// Set Last-Modified
	w.Header().Set("Last-Modified", stat.ModTime().UTC().Format(http.TimeFormat))

	// Determine content type
	ext := strings.ToLower(filepath.Ext(fsPath))
	contentType := getContentType(fsPath)

	_ = ext // might use later

	// Serve the file using http.ServeContent for range request support
	http.ServeContent(w, r, filename, stat.ModTime(), f)

	_ = contentType
}
