package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

type Config struct {
	Path                 string
	Port                 int
	Interfaces           []string
	Auth                 []AuthEntry
	AuthFile             string
	RoutePrefix          string
	RandomRoute          bool
	NoSymlinks           bool
	Hidden               bool
	SortMethod           string
	SortOrder            string
	ColorScheme          string
	ColorSchemeDark      string
	QRCode               bool
	UploadAllowed        bool
	UploadDir            string
	WebUploadConcurrency int
	ChmodEnabled         bool
	DirectorySizeEnabled bool
	MkdirEnabled         bool
	MediaType            string
	RawMediaType         string
	OnDuplicateFiles     string
	RmAllowed            bool
	RmDir                string
	EnableTar            bool
	EnableTarGz          bool
	EnableZip            bool
	CompressResponse     bool
	DirsFirst            bool
	Title                string
	Headers              []string
	ShowSymlinkInfo      bool
	HideVersionFooter    bool
	HideThemeSelector    bool
	ShowWgetFooter       bool
	TlsCert              string
	TlsKey               string
	Readme               bool
	DisableIndexing      bool
	EnableWebDav         bool
	SizeDisplay          string
	FileExternalURL      string
	Verbose              bool
	TempUploadDir        string
	SPA                  bool
	PrettyURLs           bool
	Index                string
	PrintCompletions     string
	PrintManpage         bool
}

type AuthEntry struct {
	Username string
	HashType string // "plain", "sha256", "sha512"
	Hash     string
}

func parseAuthEntry(s string) (AuthEntry, error) {
	parts := strings.SplitN(s, ":", 3)
	if len(parts) < 2 {
		return AuthEntry{}, fmt.Errorf("invalid auth format: %q", s)
	}
	entry := AuthEntry{Username: parts[0]}
	if len(parts) == 2 {
		entry.HashType = "plain"
		entry.Hash = parts[1]
	} else {
		switch strings.ToLower(parts[1]) {
		case "sha256":
			entry.HashType = "sha256"
			entry.Hash = parts[2]
		case "sha512":
			entry.HashType = "sha512"
			entry.Hash = parts[2]
		default:
			return AuthEntry{}, fmt.Errorf("unknown hash type: %q", parts[1])
		}
	}
	return entry, nil
}

func loadAuthFile(path string) ([]AuthEntry, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	var entries []AuthEntry
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		entry, err := parseAuthEntry(line)
		if err != nil {
			return nil, fmt.Errorf("invalid auth file entry %q: %v", line, err)
		}
		entries = append(entries, entry)
	}
	return entries, scanner.Err()
}

func defaultConfig() *Config {
	return &Config{
		Port:             8080,
		SortMethod:       "name",
		SortOrder:        "desc",
		ColorScheme:      "squirrel",
		ColorSchemeDark:  "archlinux",
		OnDuplicateFiles: "error",
		SizeDisplay:      "human",
	}
}

func parseArgs(args []string) (*Config, error) {
	config := defaultConfig()
	i := 0
	for i < len(args) {
		arg := args[i]
		if arg == "--" {
			i++
			if i < len(args) {
				config.Path = args[i]
			}
			break
		}
		if !strings.HasPrefix(arg, "-") {
			config.Path = arg
			i++
			continue
		}
		// Check for --flag=value
		flagName := arg
		flagValue := ""
		hasValue := false
		if strings.HasPrefix(arg, "--") {
			if idx := strings.IndexByte(arg[2:], '='); idx >= 0 {
				flagName = arg[:idx+2]
				flagValue = arg[idx+3:]
				hasValue = true
			}
		}
		switch flagName {
		case "-v", "--verbose": config.Verbose = true
		case "--spa": config.SPA = true
		case "--pretty-urls": config.PrettyURLs = true
		case "-P", "--no-symlinks": config.NoSymlinks = true
		case "-H", "--hidden": config.Hidden = true
		case "-q", "--qrcode": config.QRCode = true
		case "-r", "--enable-tar": config.EnableTar = true
		case "-g", "--enable-tar-gz": config.EnableTarGz = true
		case "-z", "--enable-zip": config.EnableZip = true
		case "-C", "--compress-response": config.CompressResponse = true
		case "-D", "--dirs-first": config.DirsFirst = true
		case "-l", "--show-symlink-info": config.ShowSymlinkInfo = true
		case "-F", "--hide-version-footer": config.HideVersionFooter = true
		case "--hide-theme-selector": config.HideThemeSelector = true
		case "-W", "--show-wget-footer": config.ShowWgetFooter = true
		case "--random-route": config.RandomRoute = true
		case "--readme": config.Readme = true
		case "-I", "--disable-indexing": config.DisableIndexing = true
		case "--enable-webdav": config.EnableWebDav = true
		case "--print-manpage": config.PrintManpage = true
		case "--chmod": config.ChmodEnabled = true
		case "--directory-size": config.DirectorySizeEnabled = true
		case "-h", "--help": printHelp(); os.Exit(0)
		case "-V", "--version": fmt.Printf("miniserve %s\n", VERSION); os.Exit(0)
		case "-p", "--port":
			v, err := nextArg(args, &i, hasValue, flagValue, flagName)
			if err != nil { return nil, err }
			if _, err := fmt.Sscanf(v, "%d", &config.Port); err != nil {
				return nil, fmt.Errorf("invalid port: %s", v)
			}
		case "-i", "--interfaces":
			v, err := nextArg(args, &i, hasValue, flagValue, flagName)
			if err != nil { return nil, err }
			config.Interfaces = append(config.Interfaces, v)
		case "-a", "--auth":
			v, err := nextArg(args, &i, hasValue, flagValue, flagName)
			if err != nil { return nil, err }
			entry, err := parseAuthEntry(v)
			if err != nil { return nil, err }
			config.Auth = append(config.Auth, entry)
		case "--auth-file":
			v, err := nextArg(args, &i, hasValue, flagValue, flagName)
			if err != nil { return nil, err }
			config.AuthFile = v
		case "--route-prefix":
			v, err := nextArg(args, &i, hasValue, flagValue, flagName)
			if err != nil { return nil, err }
			config.RoutePrefix = v
		case "-S", "--default-sorting-method":
			v, err := nextArg(args, &i, hasValue, flagValue, flagName)
			if err != nil { return nil, err }
			config.SortMethod = v
		case "-O", "--default-sorting-order":
			v, err := nextArg(args, &i, hasValue, flagValue, flagName)
			if err != nil { return nil, err }
			config.SortOrder = v
		case "-c", "--color-scheme":
			v, err := nextArg(args, &i, hasValue, flagValue, flagName)
			if err != nil { return nil, err }
			config.ColorScheme = v
		case "-d", "--color-scheme-dark":
			v, err := nextArg(args, &i, hasValue, flagValue, flagName)
			if err != nil { return nil, err }
			config.ColorSchemeDark = v
		case "-t", "--title":
			v, err := nextArg(args, &i, hasValue, flagValue, flagName)
			if err != nil { return nil, err }
			config.Title = v
		case "--header":
			v, err := nextArg(args, &i, hasValue, flagValue, flagName)
			if err != nil { return nil, err }
			config.Headers = append(config.Headers, v)
		case "--index":
			v, err := nextArg(args, &i, hasValue, flagValue, flagName)
			if err != nil { return nil, err }
			config.Index = v
		case "--temp-directory":
			v, err := nextArg(args, &i, hasValue, flagValue, flagName)
			if err != nil { return nil, err }
			config.TempUploadDir = v
		case "--tls-cert":
			v, err := nextArg(args, &i, hasValue, flagValue, flagName)
			if err != nil { return nil, err }
			config.TlsCert = v
		case "--tls-key":
			v, err := nextArg(args, &i, hasValue, flagValue, flagName)
			if err != nil { return nil, err }
			config.TlsKey = v
		case "--print-completions":
			v, err := nextArg(args, &i, hasValue, flagValue, flagName)
			if err != nil { return nil, err }
			config.PrintCompletions = v
		case "-o", "--on-duplicate-files":
			v, err := nextArg(args, &i, hasValue, flagValue, flagName)
			if err != nil { return nil, err }
			config.OnDuplicateFiles = v
		case "--size-display":
			v, err := nextArg(args, &i, hasValue, flagValue, flagName)
			if err != nil { return nil, err }
			config.SizeDisplay = v
		case "--file-external-url":
			v, err := nextArg(args, &i, hasValue, flagValue, flagName)
			if err != nil { return nil, err }
