func humanizeSize(size int64) string {
	if size < 1024 {
		return fmt.Sprintf("%d B", size)
	}
	f := float64(size)
	units := []string{"KiB", "MiB", "GiB", "TiB", "PiB", "EiB"}
	idx := 0
	for f >= 1024.0 && idx < len(units)-1 {
		f /= 1024.0
		idx++
	}
	return fmt.Sprintf("%.1f %s", f, units[idx])
}

func humanizeTime(t time.Time) string {
	elapsed := time.Since(t)
	if elapsed < 0 {
		return "in the future"
	}
	s := int64(elapsed.Seconds())
	if s <= 10 {
		return "now"
	}
	if s <= 45 {
		return fmt.Sprintf("%d seconds ago", s)
	}
	if s <= 90 {
		return "a minute ago"
	}
	if s <= 2759 {
		return fmt.Sprintf("%d minutes ago", int64(math.Round(float64(s)/60.0)))
	}
	if s <= 5459 {
		return "an hour ago"
	}
	if s <= 82799 {
		return fmt.Sprintf("%d hours ago", int64(math.Round(float64(s)/3600.0)))
	}
	if s <= 133199 {
		return "a day ago"
	}
	if s <= 604799 {
		return fmt.Sprintf("%d days ago", int64(math.Round(float64(s)/86400.0)))
	}
	if s <= 950399 {
		return "a week ago"
	}
	if s <= 2505599 {
		return fmt.Sprintf("%d weeks ago", int64(math.Round(float64(s)/(7*86400.0))))
	}
	if s <= 3974399 {
