	units := []string{"KiB", "MiB", "GiB", "TiB", "PiB", "EiB"}
	idx := 0
	for f >= 1024.0 && idx < len(units)-1 {
		f /= 1024.0
		idx++
	}
	return fmt.Sprintf("%.1f %s", f, units[idx])
}

func humanizeTime(t time.Time) string {
	elapsed := time.Since(t)
	if elapsed < 0 {
		return "in the future"
	}
	s := int64(elapsed.Seconds())
	if s <= 10 {
		return "now"
	}
	if s <= 45 {
		return fmt.Sprintf("%d seconds ago", s)
	}
	if s <= 90 {
		return "a minute ago"
	}
	if s <= 2759 {
		return fmt.Sprintf("%d minutes ago", int64(math.Round(float64(s)/60.0)))
	}
	if s <= 5459 {
		return "an hour ago"
	}
	if s <= 82799 {
		return fmt.Sprintf("%d hours ago", int64(math.Round(float64(s)/3600.0)))
	}
	if s <= 133199 {
		return "a day ago"
	}
	if s <= 604799 {
		return fmt.Sprintf("%d days ago", int64(math.Round(float64(s)/86400.0)))
	}
	if s <= 950399 {
		return "a week ago"
	}
	if s <= 2505599 {
		return fmt.Sprintf("%d weeks ago", int64(math.Round(float64(s)/(7*86400.0))))
	}
	if s <= 3974399 {
		return "a month ago"
	}
	if s <= 29808000 {
		return fmt.Sprintf("%d months ago", int64(math.Round(float64(s)/(30*86400.0))))
	}
	y := int64(math.Round(float64(s) / (365 * 86400.0)))
	if y == 1 {
		return "a year ago"
	}
	return fmt.Sprintf("%d years ago", y)
}

func formatDatetime(t time.Time) string {
	return t.UTC().Format("2006-01-02 15:04:05 +00:00 ")
}

func encodePathForURL(p string) string {
	// Encode each path component separately
	parts := strings.Split(p, "/")
	for i, part := range parts {
		// url.PathEscape encodes everything except: letters, digits, -_.~!$&'()*+,;=:@/
		// We want to encode everything except unreserved chars
		parts[i] = encodePathSegment(part)
	}
	return strings.Join(parts, "/")
}

func encodePathSegment(s string) string {
	var result strings.Builder
	for _, r := range s {
		if isUnreserved(r) {
			result.WriteRune(r)
		} else {
			// Encode as UTF-8 bytes percent-encoded
			encoded := url.PathEscape(string(r))
			result.WriteString(encoded)
		}
	}
	return result.String()
}

func isUnreserved(r rune) bool {
	return (r >= 'A' && r <= 'Z') ||
		(r >= 'a' && r <= 'z') ||
		(r >= '0' && r <= '9') ||
		r == '-' || r == '_' || r == '.' || r == '~'
}

func escapeHTML(s string) string {
	s = strings.ReplaceAll(s, "&", "&amp;")
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	s = strings.ReplaceAll(s, "\"", "&quot;")
	return s
}

func urlDecode(s string) (string, error) {
	return url.PathUnescape(s)
}

func isSubPath(parent, child string) bool {
	parent = filepath.Clean(parent)
	child = filepath.Clean(child)
	rel, err := filepath.Rel(parent, child)
	if err != nil {
		return false
	}
	return !strings.HasPrefix(rel, "..")
}

func generateETag(stat os.FileInfo) string {
	// ETag format: "inode:size:mtime_sec:mtime_nsec" all in hex
	// Get inode from stat
	sys := stat.Sys()
	var inode uint64
	if s, ok := sys.(*syscallStat); ok {
		inode = s.Ino
	}
	size := stat.Size()
	mtime := stat.ModTime()
	mtimeSec := mtime.Unix()
	mtimeNsec := mtime.UnixNano() % 1e9
	return fmt.Sprintf("%x:%x:%x:%x", inode, size, mtimeSec, mtimeNsec)
}

func getContentType(path string) string {
	ext := strings.ToLower(filepath.Ext(path))
	switch ext {
	case ".html", ".htm":
