package main

import (
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

type miniserveHandler struct {
	config *Config
}

func (h *miniserveHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	config := h.config

	// Add custom headers
	for _, header := range config.Headers {
		parts := strings.SplitN(header, ":", 2)
		if len(parts) == 2 {
			name := strings.TrimSpace(parts[0])
			value := strings.TrimSpace(parts[1])
			if w.Header().Get(name) == "" {
				w.Header().Set(name, value)
			}
		}
	}

	// Check authentication
	if len(config.Auth) > 0 {
		if !checkAuth(w, r, config.Auth) {
			return
		}
	}

	urlPath := r.URL.Path
	prefix := config.RoutePrefix

	// Check internal routes
	internalPrefix := prefix + "/__miniserve_internal"
	if strings.HasPrefix(urlPath, internalPrefix) {
		h.serveInternal(w, r, urlPath[len(internalPrefix):], config)
		return
	}

	// Check/strip prefix
	if prefix != "" {
		if urlPath == prefix || urlPath == "" {
			http.Redirect(w, r, prefix+"/", http.StatusFound)
			return
		}
		if !strings.HasPrefix(urlPath, prefix+"/") {
			ts := logTimestamp()
			fmt.Fprintf(os.Stderr, "%s [ERROR] Route %s could not be found\n", ts, urlPath)
			h.serveError(w, r, http.StatusNotFound, fmt.Sprintf("Route %s could not be found", urlPath), config)
			return
		}
		urlPath = urlPath[len(prefix):]
		if urlPath == "" {
			urlPath = "/"
		}
	}

	// WebDAV support
	if config.EnableWebDav && r.Method == "PROPFIND" {
		h.handleWebDAV(w, r, urlPath, config)
		return
	}

	switch r.Method {
	case http.MethodGet, http.MethodHead:
		h.handleGet(w, r, urlPath, config)
	case http.MethodPost:
		if strings.HasPrefix(urlPath, "/upload") {
			h.handleUpload(w, r, urlPath, config)
		} else if strings.HasPrefix(urlPath, "/rm") {
			h.handleDelete(w, r, urlPath, config)
		} else {
			h.serveError(w, r, http.StatusNotFound, fmt.Sprintf("Route %s could not be found", r.URL.Path), config)
		}
	default:
		w.WriteHeader(http.StatusMethodNotAllowed)
	}
}

func (h *miniserveHandler) serveInternal(w http.ResponseWriter, r *http.Request, subPath string, config *Config) {
	switch subPath {
	case "/style.css":
		css := generateCSS(config)
		w.Header().Set("Content-Type", "text/css; charset=utf-8")
		w.Write(css)
	case "/favicon.svg":
		w.Header().Set("Content-Type", "image/svg+xml")
		w.Write([]byte(faviconContent))
	case "/api":
		h.handleAPI(w, r, config)
	default:
		ts := logTimestamp()
		fmt.Fprintf(os.Stderr, "%s [ERROR] Route %s could not be found\n", ts, r.URL.Path)
		h.serveError(w, r, http.StatusNotFound, fmt.Sprintf("Route %s could not be found", r.URL.Path), config)
	}
}

func (h *miniserveHandler) handleGet(w http.ResponseWriter, r *http.Request, urlPath string, config *Config) {
	// Decode URL path
	decodedPath, err := urlDecode(urlPath)
	if err != nil {
		h.serveError(w, r, http.StatusBadRequest, "Invalid URL path", config)
		return
	}

	// Build filesystem path
	fsPath := filepath.Join(config.Path, filepath.FromSlash(decodedPath))

	// Security check
	if !isSubPath(config.Path, fsPath) {
		h.serveError(w, r, http.StatusForbidden, "Access denied", config)
		return
	}

	// Stat the file
	lstat, err := os.Lstat(fsPath)
	if err != nil {
		if os.IsNotExist(err) {
			// Try SPA fallback
			if config.SPA && config.Index != "" {
				indexPath := filepath.Join(config.Path, config.Index)
				if _, serr := os.Stat(indexPath); serr == nil {
					h.serveStaticFile(w, r, indexPath, config)
					return
				}
			}
			// Try pretty URLs
			if config.PrettyURLs && !strings.HasSuffix(urlPath, ".html") {
				htmlPath := fsPath + ".html"
				if _, serr := os.Stat(htmlPath); serr == nil {
					h.serveStaticFile(w, r, htmlPath, config)
					return
				}
			}
			ts := logTimestamp()
			fmt.Fprintf(os.Stderr, "%s [ERROR] Route %s could not be found\n", ts, r.URL.Path)
			h.serveError(w, r, http.StatusNotFound, fmt.Sprintf("Route %s could not be found", urlPath), config)
		} else {
			h.serveError(w, r, http.StatusInternalServerError, "Error accessing path", config)
		}
		return
	}

	// Handle symlinks
	var stat os.FileInfo
	if lstat.Mode()&os.ModeSymlink != 0 {
		if config.NoSymlinks {
			ts := logTimestamp()
			fmt.Fprintf(os.Stderr, "%s [ERROR] Route %s could not be found\n", ts, r.URL.Path)
			h.serveError(w, r, http.StatusNotFound, fmt.Sprintf("Route %s could not be found", urlPath), config)
			return
		}
		stat, err = os.Stat(fsPath)
		if err != nil {
			ts := logTimestamp()
			fmt.Fprintf(os.Stderr, "%s [ERROR] Route %s could not be found\n", ts, r.URL.Path)
			h.serveError(w, r, http.StatusNotFound, fmt.Sprintf("Route %s could not be found", urlPath), config)
			return
		}
	} else {
		stat = lstat
	}

	if stat.IsDir() {
		// Redirect if no trailing slash
		if !strings.HasSuffix(r.URL.Path, "/") {
			http.Redirect(w, r, r.URL.Path+"/", http.StatusTemporaryRedirect)
			return
		}

		// Check for index file
		if config.Index != "" {
			indexPath := filepath.Join(fsPath, config.Index)
			if _, err := os.Stat(indexPath); err == nil {
				h.serveStaticFile(w, r, indexPath, config)
				return
			}
		}

		// Handle archive download requests
		if dlType := r.URL.Query().Get("download"); dlType != "" {
			h.serveArchive(w, r, fsPath, urlPath, dlType, config)
			return
		}

		// Check if indexing is disabled
		if config.DisableIndexing && r.URL.Query().Get("raw") != "true" {
			ts := logTimestamp()
			fmt.Fprintf(os.Stderr, "%s [ERROR] Route %s could not be found\n", ts, r.URL.Path)
			h.serveError(w, r, http.StatusNotFound, fmt.Sprintf("Route %s could not be found", urlPath), config)
			return
		}

		h.serveListing(w, r, fsPath, urlPath, config)
	} else {
		h.serveStaticFile(w, r, fsPath, config)
	}
}

func (h *miniserveHandler) serveStaticFile(w http.ResponseWriter, r *http.Request, fsPath string, config *Config) {
	f, err := os.Open(fsPath)
	if err != nil {
		h.serveError(w, r, http.StatusInternalServerError, "Error opening file", config)
		return
	}
	defer f.Close()

	stat, err := f.Stat()
	if err != nil {
		h.serveError(w, r, http.StatusInternalServerError, "Error stating file", config)
		return
	}

	// Set ETag
	etag := generateETag(stat)
	w.Header().Set("ETag", etag)
	w.Header().Set("Accept-Ranges", "bytes")

	// Check if-none-match
	ifNoneMatch := r.Header.Get("If-None-Match")
	if ifNoneMatch == etag {
		w.WriteHeader(http.StatusNotModified)
		return
	}

	// Set content-disposition
	filename := filepath.Base(fsPath)
	w.Header().Set("Content-Disposition", fmt.Sprintf("inline; filename=%q", filename))

	// Set Last-Modified
	w.Header().Set("Last-Modified", stat.ModTime().UTC().Format(http.TimeFormat))

	// Set content type
	ct := getContentType(fsPath)
	if ct != "" {
		w.Header().Set("Content-Type", ct)
	}

	// Use http.ServeContent for range request support
	http.ServeContent(w, r, filename, stat.ModTime(), f)
}

func (h *miniserveHandler) handleAPI(w http.ResponseWriter, r *http.Request, config *Config) {
	if r.Method != http.MethodPost {
		w.WriteHeader(http.StatusMethodNotAllowed)
		return
	}

	var req struct {
		DirSize string `json:"DirSize"`
	}

	body, err := io.ReadAll(io.LimitReader(r.Body, 1024))
	if err != nil {
		w.WriteHeader(http.StatusBadRequest)
		return
	}

	// Simple JSON parsing
	import_json_parse(&req, body)

	if req.DirSize != "" {
		if !config.DirectorySizeEnabled {
			w.Write([]byte("-"))
			return
		}

		// Calculate directory size
		decodedPath, err := urlDecode(req.DirSize)
		if err != nil {
			w.Write([]byte("-"))
			return
		}

		fsPath := filepath.Join(config.Path, filepath.FromSlash(decodedPath))
		if !isSubPath(config.Path, fsPath) {
			w.Write([]byte("-"))
			return
		}

		size, err := calcDirSize(fsPath)
		if err != nil {
			w.Write([]byte("-"))
			return
		}

		if config.SizeDisplay == "exact" {
			w.Write([]byte(fmt.Sprintf("%d B", size)))
		} else {
			w.Write([]byte(humanizeSize(size)))
		}
		return
	}

	w.WriteHeader(http.StatusNotFound)
}

func calcDirSize(path string) (int64, error) {
	var total int64
	err := filepath.Walk(path, func(_ string, info os.FileInfo, err error) error {
		if err != nil {
			return nil // ignore errors
		}
		if !info.IsDir() {
			total += info.Size()
		}
		return nil
	})
	return total, err
}

func (h *miniserveHandler) serveError(w http.ResponseWriter, r *http.Request, code int, msg string, config *Config) {
	w.Header().Set("Content-Type", "text/html")
	w.WriteHeader(code)

	title := fmt.Sprintf("%d %s", code, http.StatusText(code))

	prefix := config.RoutePrefix
	internalBase := prefix + "/__miniserve_internal"

	html := generateErrorPage(title, msg, internalBase, config)
	w.Write(html)
}
