package main

import (
	"crypto/sha256"
	"crypto/sha512"
	"encoding/hex"
	"fmt"
	"net/http"
	"os"
	"strings"
)

func checkAuth(w http.ResponseWriter, r *http.Request, authEntries []AuthEntry) bool {
	username, password, ok := r.BasicAuth()
	if !ok {
		w.Header().Set("WWW-Authenticate", "Basic")
		w.WriteHeader(http.StatusUnauthorized)
		return false
	}

	for _, entry := range authEntries {
		if entry.Username == username {
			if verifyPassword(password, entry) {
				return true
			}
		}
	}

	ts := logTimestamp()
	fmt.Fprintf(os.Stderr, "%s [ERROR] Invalid credentials for HTTP authentication\n", ts)

	w.Header().Set("WWW-Authenticate", "Basic")
	w.WriteHeader(http.StatusUnauthorized)
	return false
}

func verifyPassword(password string, entry AuthEntry) bool {
	switch entry.HashType {
	case "plain":
		return password == entry.Hash
	case "sha256":
		h := sha256.Sum256([]byte(password))
		return strings.EqualFold(hex.EncodeToString(h[:]), entry.Hash)
	case "sha512":
		h := sha512.Sum512([]byte(password))
		return strings.EqualFold(hex.EncodeToString(h[:]), entry.Hash)
	}
	return false
}
