func buildTitleText(host, urlPath string) string {
	if urlPath == "/" {
		return host
	}
	// Remove trailing slash
	path := strings.TrimSuffix(urlPath, "/")
	// Get the last segment
	parts := strings.Split(path, "/")
	return host + "/" + strings.Join(parts[1:], "/")
}

func buildBreadcrumb(host, urlPath, prefix string) string {
	var b strings.Builder
	b.WriteString(`<h1 class="title" dir="ltr">`)

	if urlPath == "/" {
		b.WriteString(fmt.Sprintf(`<span><bdi>%s</bdi></span>/`, escapeHTML(host)))
	} else {
		// Link back to root
		b.WriteString(fmt.Sprintf(`<a href="%s/"><bdi>%s</bdi></a>/`, prefix, escapeHTML(host)))

		// Build path segments
		parts := strings.Split(strings.Trim(urlPath, "/"), "/")
		for i, part := range parts {
			if i == len(parts)-1 {
				// Last segment - not a link
				b.WriteString(fmt.Sprintf(`<span><bdi>%s</bdi></span>/`, escapeHTML(part)))
			} else {
				// Not last - link
				linkPath := prefix + "/" + strings.Join(parts[:i+1], "/") + "/"
				b.WriteString(fmt.Sprintf(`<a href="%s"><bdi>%s</bdi></a>/`, escapeHTML(linkPath), escapeHTML(part)))
			}
		}
	}

	b.WriteString("</h1>")
	return b.String()
}

