func buildTitleText(host, urlPath string) string {
	if urlPath == "/" {
		return host
	}
	// Remove trailing slash
	path := strings.TrimSuffix(urlPath, "/")
	// Get the last segment
	parts := strings.Split(path, "/")
	return host + "/" + strings.Join(parts[1:], "/")
}

func buildBreadcrumb(host, urlPath, prefix string) string {
	var b strings.Builder
	b.WriteString(`<h1 class="title" dir="ltr">`)

	if urlPath == "/" {
		b.WriteString(fmt.Sprintf(`<span><bdi>%s</bdi></span>/`, escapeHTML(host)))
	} else {
		// Link back to root
		b.WriteString(fmt.Sprintf(`<a href="%s/"><bdi>%s</bdi></a>/`, prefix, escapeHTML(host)))

		// Build path segments
		parts := strings.Split(strings.Trim(urlPath, "/"), "/")
		for i, part := range parts {
			if i == len(parts)-1 {
				// Last segment - not a link
				b.WriteString(fmt.Sprintf(`<span><bdi>%s</bdi></span>/`, escapeHTML(part)))
			} else {
				// Not last - link
				linkPath := prefix + "/" + strings.Join(parts[:i+1], "/") + "/"
				b.WriteString(fmt.Sprintf(`<a href="%s"><bdi>%s</bdi></a>/`, escapeHTML(linkPath), escapeHTML(part)))
			}
		}
	}

	b.WriteString("</h1>")
	return b.String()
}

func buildTableHeader(sortMethod, sortOrder string, sortActive bool, hasActions bool) string {
	var b strings.Builder

	for _, col := range []struct{ name, key, label string }{
		{"name", "name", "Name"},
		{"size", "size", "Size"},
		{"date", "date", "Last modification"},
	} {
		isActive := sortActive && sortMethod == col.key
		b.WriteString(fmt.Sprintf(`<th class="%s">`, col.name))

		var spanClass string
		if isActive {
			spanClass = "active"
		}
		b.WriteString(fmt.Sprintf(`<span class="%s">`, spanClass))

		var chevron string
		var linkOrder string
		var linkTitle string

		if isActive {
			if sortOrder == "asc" {
				chevron = "▴"
				linkOrder = "desc"
				linkTitle = fmt.Sprintf("Sort by %s in descending order", col.label)
			} else {
				chevron = "▾"
				linkOrder = "asc"
				linkTitle = fmt.Sprintf("Sort by %s in ascending order", col.label)
			}
		} else {
			chevron = "▾"
			linkOrder = "asc"
			linkTitle = fmt.Sprintf("Sort by %s in ascending order", col.label)
		}

		b.WriteString(fmt.Sprintf(`<span class="chevron">%s</span>`, chevron))
		b.WriteString(fmt.Sprintf(`<a href="?sort=%s&amp;order=%s" title="%s">%s</a>`, col.key, linkOrder, escapeHTML(linkTitle), col.label))
		b.WriteString("</span>")
		b.WriteString("</th>")
	}

	if hasActions {
		b.WriteString(`<th class="actions"><span>Actions</span></th>`)
	}

	return b.String()
}

func buildEntryRow(entry fileEntry, sortMethod, sortOrder string, sortActive bool, config *Config, currentPath, prefix string) string {
	var b strings.Builder

	entryType := "file"
	if entry.IsDir {
		entryType = "directory"
	}

	b.WriteString(fmt.Sprintf(`<tr class="entry-type-%s">`, entryType))
	b.WriteString("<td>")
	b.WriteString("<p>")

	// Name column
	var linkClass string
	var encodedURL string

	if entry.IsSymlink && config.ShowSymlinkInfo {
		linkClass = "symlink"
		if entry.IsDir {
			encodedURL = encodePathForURL(entry.Path) + "/"
		} else {
			encodedURL = encodePathForURL(entry.Path)
		}
	} else if entry.IsDir {
		linkClass = "directory"
		encodedURL = encodePathForURL(entry.Path) + "/"
	} else {
		linkClass = "file"
		encodedURL = encodePathForURL(entry.Path)
	}

	// Handle external URL for files
	if !entry.IsDir && config.FileExternalURL != "" {
		encodedURL = config.FileExternalURL + encodedURL
	}

	// Display name
	displayName := entry.Name
	if entry.IsDir {
		displayName += "/"
	}

	if entry.IsSymlink && config.ShowSymlinkInfo {
		// Symlink display: <a class="symlink" href="...">name<span class="symlink-symbol"></span><a class="dir/file">target</a></a>
		b.WriteString(fmt.Sprintf(`<a class="%s" href="%s">%s<span class="symlink-symbol"></span>`,
			linkClass, escapeHTML(encodedURL), escapeHTML(displayName)))

		targetClass := "file"
		targetDisplay := entry.SymlinkTarget
		if entry.IsDir {
			targetClass = "directory"
			targetDisplay += "/"
		}
		b.WriteString(fmt.Sprintf(`<a class="%s">%s</a>`, targetClass, escapeHTML(targetDisplay)))
		b.WriteString("</a>")
	} else {
		b.WriteString(fmt.Sprintf(`<a class="%s" href="%s">%s</a>`, linkClass, escapeHTML(encodedURL), escapeHTML(displayName)))
	}

	// Mobile info spans (for files only)
	if !entry.IsDir {
		// Size mobile info
		b.WriteString(`<span class="mobile-info size">`)
		b.WriteString(buildSortSpan("size", sortMethod, sortOrder, sortActive, formatFileSize(entry.Stat, config)))
		b.WriteString("</span>")

		// Date mobile info
		b.WriteString(`<span class="mobile-info history">`)
		b.WriteString(buildSortSpan("date", sortMethod, sortOrder, sortActive, humanizeTime(entry.Stat.ModTime())))
		b.WriteString("</span>")
	}

	b.WriteString("</p>")
	b.WriteString("</td>")

	// Size column
	if entry.IsDir {
		b.WriteString(`<td class="size-cell"></td>`)
	} else {
		sizeStr := formatFileSize(entry.Stat, config)
		b.WriteString(fmt.Sprintf(`<td class="size-cell">%s</td>`, sizeStr))
	}

	// Date column
	dateStr := formatDatetime(entry.Stat.ModTime())
	historyStr := humanizeTime(entry.Stat.ModTime())
	b.WriteString(fmt.Sprintf(`<td class="date-cell"><span>%s</span><span class="history">%s</span></td>`,
		escapeHTML(dateStr), escapeHTML(historyStr)))

	// Actions column (if rm is enabled)
	if config.RmAllowed && isRmAllowedForPath(currentPath, config) {
		rmPath := entry.Path
		if entry.IsDir {
			rmPath = strings.TrimSuffix(rmPath, "/")
		}
		rmAction := prefix + "/rm?path=" + encodePathForURL(rmPath)
		b.WriteString(fmt.Sprintf(`<td class="actions-cell"><form class="rm_form" action="%s" method="POST"><button type="submit" title="Delete">✗</button></form></td>`,
			escapeHTML(rmAction)))
	}

	b.WriteString("</tr>")
	return b.String()
}

func buildSortSpan(colKey, sortMethod, sortOrder string, sortActive bool, content string) string {
	isActive := sortActive && sortMethod == colKey
	var spanClass, chevron, linkOrder, linkTitle string

	if isActive {
		spanClass = "active"
		if sortOrder == "asc" {
			chevron = "▴"
			linkOrder = "desc"
			linkTitle = fmt.Sprintf("Sort by %s in descending order", colKey)
		} else {
			chevron = "▾"
			linkOrder = "asc"
			linkTitle = fmt.Sprintf("Sort by %s in ascending order", colKey)
		}
	} else {
		spanClass = ""
		chevron = "▾"
		linkOrder = "asc"
		colLabel := colKey
		if colKey == "date" {
			colLabel = "date"
		}
		linkTitle = fmt.Sprintf("Sort by %s in ascending order", colLabel)
	}

	return fmt.Sprintf(`<span class="%s"><span class="chevron">%s</span><a href="?sort=%s&amp;order=%s" title="%s">%s</a></span>`,
		spanClass, chevron, colKey, linkOrder, escapeHTML(linkTitle), escapeHTML(content))
}

func formatFileSize(stat os.FileInfo, config *Config) string {
	if stat == nil {
		return "0 B"
	}
	if config.SizeDisplay == "exact" {
		return fmt.Sprintf("%d B", stat.Size())
	}
	return humanizeSize(stat.Size())
}

func readDirEntries(fsPath, urlPath string, config *Config) ([]fileEntry, error) {
	entries, err := os.ReadDir(fsPath)
	if err != nil {
		return nil, err
	}

	var result []fileEntry
	for _, entry := range entries {
		name := entry.Name()

		// Skip hidden files unless --hidden flag is set
		if !config.Hidden && strings.HasPrefix(name, ".") {
			continue
		}

		// Build entry path
		var entryURLPath string
		if urlPath == "/" {
			entryURLPath = "/" + name
		} else {
			entryURLPath = urlPath + name
		}

		entryFSPath := filepath.Join(fsPath, name)

		var stat os.FileInfo
		var isSymlink bool
		var symlinkTarget string

		// Check for symlink
		lstat, err := os.Lstat(entryFSPath)
		if err != nil {
			continue
		}

		if lstat.Mode()&os.ModeSymlink != 0 {
			if config.NoSymlinks {
				continue
			}
			isSymlink = true
			// Read symlink target
			target, err := os.Readlink(entryFSPath)
			if err == nil {
				symlinkTarget = target
			}
			stat, err = os.Stat(entryFSPath)
			if err != nil {
				// Broken symlink - skip
				continue
			}
		} else {
			stat = lstat
		}

		result = append(result, fileEntry{
			Name:          name,
			Path:          entryURLPath,
			FSPath:        entryFSPath,
			IsDir:         stat.IsDir(),
			Size:          stat.Size(),
			IsSymlink:     isSymlink,
			SymlinkTarget: symlinkTarget,
			Stat:          stat,
		})
	}

	return result, nil
}

func sortEntries(entries []fileEntry, method, order string, dirsFirst bool) {
	sort.SliceStable(entries, func(i, j int) bool {
		a, b := entries[i], entries[j]

		// Dirs first
		if dirsFirst {
			if a.IsDir != b.IsDir {
				return a.IsDir
			}
		}

		var less bool
		switch method {
		case "size":
			less = a.Size < b.Size
		case "date":
			less = a.Stat.ModTime().Before(b.Stat.ModTime())
		default: // name
			less = strings.ToLower(a.Name) < strings.ToLower(b.Name)
		}

		if order == "asc" {
			return less
		}
		return !less
	})
}

func isUploadAllowedForPath(urlPath string, config *Config) bool {
	if !config.UploadAllowed {
		return false
	}
	if config.UploadDir == "" {
		return true // all paths allowed
	}
	// Check if urlPath is within uploadDir
	allowed := config.UploadDir
	if !strings.HasPrefix(allowed, "/") {
		allowed = "/" + allowed
	}
	return urlPath == allowed || strings.HasPrefix(urlPath, allowed+"/")
}

func isRmAllowedForPath(urlPath string, config *Config) bool {
	if !config.RmAllowed {
		return false
	}
	if config.RmDir == "" {
		return true
	}
	allowed := config.RmDir
	if !strings.HasPrefix(allowed, "/") {
		allowed = "/" + allowed
	}
	return urlPath == allowed || strings.HasPrefix(urlPath, allowed+"/")
}

func buildAcceptAttr(config *Config) string {
	if config.RawMediaType != "" {
		return config.RawMediaType
	}
	switch config.MediaType {
	case "image":
		return "image/*"
	case "audio":
		return "audio/*"
	case "video":
		return "video/*"
	}
	return ""
}

func getRequestURL(r *http.Request, config *Config) string {
	scheme := "http"
	if r.TLS != nil {
		scheme = "https"
	}
	host := r.Host
	return fmt.Sprintf("%s://%s%s", scheme, host, r.URL.Path)
}

func generateErrorPage(title, msg, internalBase string, config *Config) []byte {
	var b strings.Builder
	b.WriteString("<!DOCTYPE html><html><head>")
	b.WriteString(`<meta charset="utf-8">`)
	b.WriteString(`<meta http-equiv="X-UA-Compatible" content="IE=edge">`)
