func (h *miniserveHandler) serveListing(w http.ResponseWriter, r *http.Request, fsPath string, urlPath string, config *Config) {
	// Read directory
	entries, err := readDirEntries(fsPath, urlPath, config)
	if err != nil {
		h.serveError(w, r, http.StatusInternalServerError, fmt.Sprintf("Error reading directory: %v", err), config)
		return
	}

	// Parse sort params
	q := r.URL.Query()
	sortMethod := q.Get("sort")
	sortOrder := q.Get("order")
	sortActive := sortMethod != ""

	if sortMethod == "" {
		sortMethod = config.SortMethod
	}
	if sortOrder == "" {
		sortOrder = config.SortOrder
	}

	// Sort entries
	sortEntries(entries, sortMethod, sortOrder, config.DirsFirst)

	// Build HTML
	prefix := config.RoutePrefix
	internalBase := prefix + "/__miniserve_internal"

	// Get the current URL for various purposes
	requestURL := getRequestURL(r, config)

	// Title/heading
	host := r.Host
	if config.Title != "" {
		host = config.Title
	}

	// Generate HTML
	var b strings.Builder

	// DOCTYPE and head
	b.WriteString("<!DOCTYPE html><html><head>")
	b.WriteString(`<meta charset="utf-8">`)
	b.WriteString(`<meta http-equiv="X-UA-Compatible" content="IE=edge">`)
	b.WriteString(`<meta name="viewport" content="width=device-width, initial-scale=1">`)
	b.WriteString(`<meta name="color-scheme" content="dark light">`)
	b.WriteString(fmt.Sprintf(`<link rel="icon" type="image/svg+xml" href="%s/favicon.svg">`, internalBase))
	b.WriteString(fmt.Sprintf(`<link rel="stylesheet" href="%s/style.css">`, internalBase))

	// Title
	titleText := buildTitleText(host, urlPath)
	b.WriteString(fmt.Sprintf("<title>%s</title>", escapeHTML(titleText)))

	// Theme script
	b.WriteString("<script>\n" + themeScript + "\n</script>")

	// Dir size script
	apiRoute := internalBase + "/api"
	b.WriteString(fmt.Sprintf("<script>%s</script>", buildDirSizeScript(apiRoute)))

	// Upload script if upload enabled
	if config.UploadAllowed && isUploadAllowedForPath(urlPath, config) {
		concurrency := config.WebUploadConcurrency
		b.WriteString(fmt.Sprintf("<script>%s</script>", buildUploadScript(concurrency)))
	}

	b.WriteString("</head>")

	// Body
	b.WriteString(`<body id="drop-container">`)

	// Drag form (only if upload enabled for this path)
	if config.UploadAllowed && isUploadAllowedForPath(urlPath, config) {
		b.WriteString(`<div class="toolbar_box_group"><div class="drag-form"><div class="form_title"><h1>Drop your file here to upload it</h1></div></div></div>`)
	} else {
		b.WriteString(`<div class="toolbar_box_group"></div>`)
	}

	// Nav (QR code and theme selector)
	b.WriteString("<nav>")
	if config.QRCode {
		qrSVG := generateQRCode(requestURL)
		b.WriteString(`<div>`)
		b.WriteString("<p>QR code</p>")
		b.WriteString(fmt.Sprintf(`<div class="qrcode" id="qrcode" title="%s">%s</div>`, escapeHTML(requestURL), qrSVG))
		b.WriteString("</div>")
