	if !config.HideThemeSelector {
		b.WriteString("<div>")
		b.WriteString("<p>Change theme...</p>")
		b.WriteString(`<ul class="theme">`)
		b.WriteString(`<li data-theme="default"><a href="javascript:updateColorScheme(&quot;default&quot;)" title="Switch to Default (light/dark) theme">Default (light/dark)</a></li>`)
		b.WriteString(`<li data-theme="squirrel"><a href="javascript:updateColorScheme(&quot;squirrel&quot;)" title="Switch to Squirrel (light) theme">Squirrel (light)</a></li>`)
		b.WriteString(`<li data-theme="archlinux"><a href="javascript:updateColorScheme(&quot;archlinux&quot;)" title="Switch to Arch Linux (dark) theme">Arch Linux (dark)</a></li>`)
		b.WriteString(`<li data-theme="zenburn"><a href="javascript:updateColorScheme(&quot;zenburn&quot;)" title="Switch to Zenburn (dark) theme">Zenburn (dark)</a></li>`)
		b.WriteString(`<li data-theme="monokai"><a href="javascript:updateColorScheme(&quot;monokai&quot;)" title="Switch to Monokai (dark) theme">Monokai (dark)</a></li>`)
		b.WriteString("</ul>")
		b.WriteString("</div>")
	}
	b.WriteString("</nav>")

	// Container
	b.WriteString(`<div class="container">`)
	b.WriteString(`<span id="top"></span>`)

	// H1 title/breadcrumb
	b.WriteString(buildBreadcrumb(host, urlPath, prefix))

	// Toolbar (downloads and upload form)
	b.WriteString(`<div class="toolbar">`)

	// Archive download links
	if config.EnableTarGz || config.EnableTar || config.EnableZip {
