			host := r.Host
			wgetCmd = fmt.Sprintf("wget -rcnp -R 'index.html*' -nH -P '%s' '%s?raw=true'", host, requestURL)
		} else {
			wgetCmd = fmt.Sprintf("wget -rcnp -R 'index.html*' -nH '%s?raw=true'", requestURL)
		}
		escapedCmd := html.EscapeString(wgetCmd)
		jsCmd := html.EscapeString(wgetCmd)
		b.WriteString(fmt.Sprintf(`<a class="cmd" title="Click to copy!" style="cursor: pointer;" onclick="navigator.clipboard.writeText(&quot;%s&quot;)">%s</a>`, jsCmd, escapedCmd))
