package main

import (
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

func (h *miniserveHandler) handleUpload(w http.ResponseWriter, r *http.Request, urlPath string, config *Config) {
	if !config.UploadAllowed {
		h.serveError(w, r, http.StatusForbidden, "File uploads are not enabled", config)
		return
	}

	// Get target path from query parameter
	targetPath := r.URL.Query().Get("path")
	if targetPath == "" {
		targetPath = "/"
	}

	// Check if upload is allowed for this path
	if !isUploadAllowedForPath(targetPath, config) {
		h.serveError(w, r, http.StatusForbidden, "Upload not allowed for this path", config)
		return
	}

	// Build filesystem target directory
	fsTargetDir := filepath.Join(config.Path, filepath.FromSlash(targetPath))
	if !isSubPath(config.Path, fsTargetDir) {
		h.serveError(w, r, http.StatusForbidden, "Access denied", config)
		return
	}

	// Parse multipart form
	err := r.ParseMultipartForm(32 << 20) // 32MB
	if err != nil {
		h.serveError(w, r, http.StatusBadRequest, fmt.Sprintf("Error parsing form: %v", err), config)
		return
	}

	// Check for mkdir request
	if mkdirName := r.FormValue("mkdir"); mkdirName != "" {
		if config.MkdirEnabled {
			newDir := filepath.Join(fsTargetDir, filepath.Clean(mkdirName))
			if !isSubPath(fsTargetDir, newDir) {
				h.serveError(w, r, http.StatusBadRequest, "Invalid directory name", config)
				return
			}
			if err := os.MkdirAll(newDir, 0755); err != nil {
				h.serveError(w, r, http.StatusInternalServerError, fmt.Sprintf("Failed to create directory: %v", err), config)
				return
			}
		}
		// Redirect back to the target path
		prefix := config.RoutePrefix
		http.Redirect(w, r, prefix+targetPath, http.StatusSeeOther)
		return
	}

	// Handle file uploads
	if r.MultipartForm == nil || len(r.MultipartForm.File) == 0 {
		h.serveError(w, r, http.StatusBadRequest, "No file uploaded", config)
		return
	}

	// Upload each file
	for _, files := range r.MultipartForm.File {
		for _, fileHeader := range files {
			if err := saveUploadedFile(fileHeader.Filename, fsTargetDir, fileHeader, config); err != nil {
				ts := logTimestamp()
				fmt.Fprintf(os.Stderr, "%s [ERROR] %v\n", ts, err)
				http.Error(w, err.Error(), http.StatusConflict)
				return
			}
		}
	}

	// Redirect back to the target path
	prefix := config.RoutePrefix
	http.Redirect(w, r, prefix+targetPath, http.StatusSeeOther)
}

func saveUploadedFile(filename, targetDir string, fileHeader interface{ Open() (io.ReadCloser, error); Filename string }, config *Config) error {
	// Sanitize filename
	safeName := filepath.Base(fileHeader.Filename)
	if safeName == "." || safeName == "/" {
		return fmt.Errorf("invalid filename")
	}

	destPath := filepath.Join(targetDir, safeName)
	if !isSubPath(targetDir, destPath) {
		return fmt.Errorf("invalid file path")
	}

	// Check for duplicates
	_, err := os.Stat(destPath)
	if err == nil {
		// File exists
		switch config.OnDuplicateFiles {
		case "error":
			return fmt.Errorf("File already exists, and the on_duplicate_files option is set to error out")
		case "overwrite":
			// proceed to overwrite
		case "rename":
			destPath = findAvailableName(destPath)
		}
	}

	// Open source
	src, err := fileHeader.Open()
	if err != nil {
		return fmt.Errorf("error opening uploaded file: %v", err)
	}
	defer src.Close()

	// Create destination file
	var dest *os.File
	if config.TempUploadDir != "" {
		// Write to temp dir first
		tempFile, err := os.CreateTemp(config.TempUploadDir, "upload-*")
		if err != nil {
			return fmt.Errorf("error creating temp file: %v", err)
		}
		tempPath := tempFile.Name()
		_, err = io.Copy(tempFile, src)
		tempFile.Close()
		if err != nil {
			os.Remove(tempPath)
			return fmt.Errorf("error writing temp file: %v", err)
		}
		if err := os.Rename(tempPath, destPath); err != nil {
			os.Remove(tempPath)
			return fmt.Errorf("error moving file: %v", err)
		}
	} else {
		dest, err = os.Create(destPath)
		if err != nil {
			return fmt.Errorf("error creating file: %v", err)
		}
		defer dest.Close()
		if _, err := io.Copy(dest, src); err != nil {
			return fmt.Errorf("error writing file: %v", err)
		}
	}

	return nil
}

func findAvailableName(destPath string) string {
	ext := filepath.Ext(destPath)
	base := strings.TrimSuffix(destPath, ext)

	for i := 1; ; i++ {
		newPath := fmt.Sprintf("%s-%d%s", base, i, ext)
		if _, err := os.Stat(newPath); os.IsNotExist(err) {
			return newPath
		}
	}
}

func (h *miniserveHandler) handleDelete(w http.ResponseWriter, r *http.Request, urlPath string, config *Config) {
	if !config.RmAllowed {
		h.serveError(w, r, http.StatusForbidden, "File deletion is not enabled", config)
		return
	}

	// Get target path from query parameter
	targetPath := r.URL.Query().Get("path")
	if targetPath == "" {
		h.serveError(w, r, http.StatusBadRequest, "Missing path parameter", config)
		return
	}

	// Check if rm is allowed for this path
	parentDir := filepath.Dir(targetPath)
	if !isRmAllowedForPath(parentDir+"/", config) {
		h.serveError(w, r, http.StatusForbidden, "Deletion not allowed for this path", config)
		return
	}

	// Build filesystem path
	fsPath := filepath.Join(config.Path, filepath.FromSlash(targetPath))
	if !isSubPath(config.Path, fsPath) {
		h.serveError(w, r, http.StatusForbidden, "Access denied", config)
		return
	}

	// Delete the file or directory
	if err := os.RemoveAll(fsPath); err != nil {
		h.serveError(w, r, http.StatusInternalServerError, fmt.Sprintf("Error deleting: %v", err), config)
		return
	}

	// Redirect to parent directory
	prefix := config.RoutePrefix
	parentURLPath := filepath.Dir(targetPath)
	if !strings.HasSuffix(parentURLPath, "/") {
		parentURLPath += "/"
	}
	http.Redirect(w, r, prefix+parentURLPath, http.StatusSeeOther)
}
GOEOF
