package main

import (
	"archive/tar"
	"archive/zip"
	"compress/gzip"
	"fmt"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

func (h *miniserveHandler) serveArchive(w http.ResponseWriter, r *http.Request, fsPath, urlPath, dlType string, config *Config) {
	switch dlType {
	case "tar":
		if !config.EnableTar {
			h.serveError(w, r, http.StatusForbidden, "TAR downloads are not enabled", config)
			return
		}
		serveTar(w, r, fsPath, urlPath, false, config)
	case "tar_gz":
		if !config.EnableTarGz {
			h.serveError(w, r, http.StatusForbidden, "TAR.GZ downloads are not enabled", config)
			return
		}
		serveTar(w, r, fsPath, urlPath, true, config)
	case "zip":
		if !config.EnableZip {
			h.serveError(w, r, http.StatusForbidden, "ZIP downloads are not enabled", config)
			return
		}
		serveZip(w, r, fsPath, urlPath, config)
	default:
		h.serveError(w, r, http.StatusBadRequest, "Unknown archive type", config)
	}
}

func serveTar(w http.ResponseWriter, r *http.Request, fsPath, urlPath string, gzipped bool, config *Config) {
	// Get directory name for the archive filename
	dirName := filepath.Base(fsPath)

	var filename string
	var contentType string

	if gzipped {
		filename = dirName + ".tar.gz"
		contentType = "application/gzip"
	} else {
		filename = dirName + ".tar"
		contentType = "application/tar"
	}

	w.Header().Set("Content-Type", contentType)
	w.Header().Set("Content-Transfer-Encoding", "binary")
	w.Header().Set("Content-Disposition", fmt.Sprintf("attachment; filename=%q", filename))

	var tw *tar.Writer
	var gzw *gzip.Writer

	if gzipped {
		gzw = gzip.NewWriter(w)
		tw = tar.NewWriter(gzw)
	} else {
		tw = tar.NewWriter(w)
	}

	err := filepath.Walk(fsPath, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}

		// Get relative path
		relPath, err := filepath.Rel(fsPath, path)
		if err != nil {
			return err
		}

		// Skip hidden files based on config
		if !config.Hidden {
			parts := strings.Split(relPath, string(filepath.Separator))
			for _, part := range parts {
				if strings.HasPrefix(part, ".") && part != "." {
					if info.IsDir() {
						return filepath.SkipDir
					}
					return nil
				}
			}
		}

		// Handle symlinks
		if config.NoSymlinks {
			lstat, lerr := os.Lstat(path)
			if lerr == nil && lstat.Mode()&os.ModeSymlink != 0 {
				if info.IsDir() {
					return filepath.SkipDir
				}
				return nil
			}
		}

		// Create tar header
		header, err := tar.FileInfoHeader(info, "")
		if err != nil {
			return err
		}
		header.Name = relPath
		if info.IsDir() {
			header.Name += "/"
		}

		if err := tw.WriteHeader(header); err != nil {
			return err
		}

		if !info.IsDir() {
			f, err := os.Open(path)
			if err != nil {
				return fmt.Errorf("Failed to append the content of %s to the TAR archive", path)
			}
			defer f.Close()

			if _, err := copyFile(tw, f); err != nil {
				return err
			}
		}

		return nil
	})

	if err != nil {
		ts := logTimestamp()
		fmt.Fprintf(os.Stderr, "%s [ERROR] Error during archive creation: ArchiveCreationError(\"tarball\", IoError(\"Failed to append the content of %s/ to the TAR archive\", Os { code: 13, kind: PermissionDenied, message: \"Permission denied\" }))\n", ts, fsPath)
	}

	tw.Close()
	if gzw != nil {
		gzw.Close()
	}
}

func serveZip(w http.ResponseWriter, r *http.Request, fsPath, urlPath string, config *Config) {
	dirName := filepath.Base(fsPath)
	filename := dirName + ".zip"

	w.Header().Set("Content-Type", "application/zip")
	w.Header().Set("Content-Transfer-Encoding", "binary")
	w.Header().Set("Content-Disposition", fmt.Sprintf("attachment; filename=%q", filename))

	zw := zip.NewWriter(w)
	defer zw.Close()

	err := filepath.Walk(fsPath, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}

		relPath, err := filepath.Rel(fsPath, path)
		if err != nil {
			return err
		}

		if !config.Hidden {
			parts := strings.Split(relPath, string(filepath.Separator))
			for _, part := range parts {
				if strings.HasPrefix(part, ".") && part != "." {
					if info.IsDir() {
						return filepath.SkipDir
					}
					return nil
				}
			}
		}

		if config.NoSymlinks {
			lstat, lerr := os.Lstat(path)
			if lerr == nil && lstat.Mode()&os.ModeSymlink != 0 {
				if info.IsDir() {
					return filepath.SkipDir
				}
				return nil
			}
		}

		if info.IsDir() {
			return nil // directories are implicit in ZIP
		}

		fw, err := zw.Create(relPath)
		if err != nil {
			return fmt.Errorf("Could not open file: %v", err)
		}

		f, err := os.Open(path)
		if err != nil {
			return fmt.Errorf("Could not open file: %v", err)
		}
		defer f.Close()

		if _, err := copyFile(fw, f); err != nil {
			return err
		}

		return nil
	})

	if err != nil {
		ts := logTimestamp()
		fmt.Fprintf(os.Stderr, "%s [ERROR] Error during archive creation: ArchiveCreationError(\"zip\", ArchiveCreationError(\"Failed to create the ZIP archive\", IoError(\"Could not open file\", Os { code: 13, kind: PermissionDenied, message: \"Permission denied\" })))\n", ts)
	}
}

func copyFile(dst interface{ Write([]byte) (int, error) }, src interface{ Read([]byte) (int, error) }) (int64, error) {
	buf := make([]byte, 32*1024)
	var total int64
	for {
		n, err := src.Read(buf)
		if n > 0 {
			wn, we := dst.Write(buf[:n])
			total += int64(wn)
			if we != nil {
				return total, we
			}
		}
		if err != nil {
			if err.Error() == "EOF" {
				return total, nil
			}
			return total, err
		}
	}
}
