package main

import (
	"fmt"
	"strings"
)

// generateQRCode generates an SVG QR code for the given URL
// Returns the SVG string (without <div> wrapper)
func generateQRCode(url string) string {
	// Generate QR code matrix
	matrix := encodeQR(url)
	if matrix == nil {
		return ""
	}

	size := len(matrix)
	viewSize := size + 2 // 1 pixel quiet zone on each side

	var svg strings.Builder
	svg.WriteString(fmt.Sprintf(`<svg viewBox="0 0 %d %d" xmlns="http://www.w3.org/2000/svg">`, viewSize, viewSize))
	svg.WriteString(fmt.Sprintf(`<rect width="%dpx" height="%dpx" fill="#ffffff"/>`, viewSize, viewSize))

	// Generate path for dark modules
	svg.WriteString(`<path d="`)
	for y := 0; y < size; y++ {
		for x := 0; x < size; x++ {
			if matrix[y][x] {
				svg.WriteString(fmt.Sprintf("M%d,%dh1v1h-1", x+1, y+1))
			}
		}
	}
	svg.WriteString(`" fill="#000000"/>`)
	svg.WriteString("</svg>")

	return svg.String()
}

// encodeQR encodes a string as a QR code matrix
// Uses a simplified implementation
func encodeQR(data string) [][]bool {
	// For simplicity, we'll implement QR code version 2 (25x25)
	// This handles URLs up to about 32 characters in alphanumeric mode
	// or up to about 20 chars in byte mode

	// Use a simple QR code library approach
	// Version 1: 21x21, Version 2: 25x25, Version 3: 29x29

	// For longer URLs, we need higher versions
	// Let's implement versions 1-10

	version := selectVersion(data)
	if version <= 0 {
		return nil
	}

	size := 17 + 4*version
	matrix := make([][]bool, size)
	for i := range matrix {
		matrix[i] = make([]bool, size)
	}

	// Add finder patterns
	addFinderPattern(matrix, 0, 0)
	addFinderPattern(matrix, size-7, 0)
	addFinderPattern(matrix, 0, size-7)

	// Add separators (already handled by finder pattern placement)

	// Add timing patterns
	for i := 8; i < size-8; i++ {
		matrix[6][i] = (i % 2) == 0
		matrix[i][6] = (i % 2) == 0
	}

	// Add dark module
	matrix[size-8][8] = true

	// Add alignment patterns (for version >= 2)
	if version >= 2 {
		positions := alignmentPatternPositions(version)
		for _, py := range positions {
			for _, px := range positions {
				if !isNearFinderPattern(py, px, size) {
					addAlignmentPattern(matrix, py, px)
				}
			}
		}
	}

	// Reserve format information area
	// (we'll place real format info after data encoding)

	// Encode data
	codewords := encodeData(data, version)

	// Add error correction
	allCodewords := addErrorCorrection(codewords, version)

	// Place data in matrix
	placeData(matrix, allCodewords, size)

	// Apply best mask
	bestMatrix := applyBestMask(matrix, version, size)

	return bestMatrix
