func selectVersion(data string) int {
	dataLen := len(data)
	// Byte mode capacity per version (error correction level M)
	capacities := []int{
		0,  // version 0 (unused)
		14, // version 1
		26, // version 2
		42, // version 3
		62, // version 4
		84, // version 5
		106, // version 6
		122, // version 7
		154, // version 8
		180, // version 9
		213, // version 10
	}

	for v, cap := range capacities {
		if cap >= dataLen {
			return v
		}
	}
	return -1
}

func addFinderPattern(matrix [][]bool, row, col int) {
	// 7x7 finder pattern
	for r := 0; r < 7; r++ {
		for c := 0; c < 7; c++ {
			// Border (row 0, row 6, col 0, col 6)
			if r == 0 || r == 6 || c == 0 || c == 6 {
				matrix[row+r][col+c] = true
			} else if r >= 2 && r <= 4 && c >= 2 && c <= 4 {
				// Inner square
				matrix[row+r][col+c] = true
			} else {
				matrix[row+r][col+c] = false
			}
		}
	}
}

func addAlignmentPattern(matrix [][]bool, row, col int) {
	for r := -2; r <= 2; r++ {
		for c := -2; c <= 2; c++ {
			if r == -2 || r == 2 || c == -2 || c == 2 || (r == 0 && c == 0) {
				matrix[row+r][col+c] = true
			} else {
				matrix[row+r][col+c] = false
			}
		}
	}
}

func isNearFinderPattern(row, col, size int) bool {
	// Check if near top-left finder
	if row <= 8 && col <= 8 {
		return true
	}
	// Check if near top-right finder
	if row <= 8 && col >= size-9 {
		return true
	}
	// Check if near bottom-left finder
	if row >= size-9 && col <= 8 {
