func encodeData(data string, version int) []byte {
	// Simplified byte mode encoding
	// Mode indicator: 0100 (byte mode)
	// Character count: 8 bits for version 1-9
	dataBytes := []byte(data)

	// Build bitstring
	bits := make([]int, 0)

	// Mode indicator: 0100
	bits = append(bits, 0, 1, 0, 0)

	// Character count (8 bits)
	l := len(dataBytes)
	for i := 7; i >= 0; i-- {
		bits = append(bits, (l>>uint(i))&1)
	}

	// Data bytes
	for _, b := range dataBytes {
		for i := 7; i >= 0; i-- {
			bits = append(bits, int(b>>uint(i))&1)
		}
	}

	// Terminator
	bits = append(bits, 0, 0, 0, 0)

	// Total capacity in bits (version M error correction)
	totalBits := dataCapacityBits(version)

	// Pad to byte boundary
	for len(bits)%8 != 0 {
		bits = append(bits, 0)
	}

	// Add pad bytes
	padBytes := []int{0xEC, 0x11}
	padIdx := 0
	for len(bits) < totalBits {
		b := padBytes[padIdx%2]
		for i := 7; i >= 0; i-- {
			bits = append(bits, (b>>uint(i))&1)
		}
		padIdx++
	}

	// Convert bits to bytes
	codewords := make([]byte, len(bits)/8)
	for i := range codewords {
		b := 0
		for j := 0; j < 8; j++ {
			b = (b << 1) | bits[i*8+j]
		}
		codewords[i] = byte(b)
	}

	return codewords
}

func dataCapacityBits(version int) int {
	// Data capacity in bits for M error correction level
	caps := []int{
		0,
		104, // v1
		208, // v2
		320, // v3
		480, // v4
		640, // v5
		800, // v6
		960, // v7
		1136, // v8
		1320, // v9
		1480, // v10
	}
	if version < 1 || version > 10 {
		return 0
	}
	return caps[version]
}

