cat > /workspace/miniserve-impl/server.go << 'GOEOF'
package main

import (
	"context"
	"crypto/tls"
	"fmt"
	"net"
	"net/http"
	"os"
	"os/signal"
	"strings"
	"syscall"
	"time"
)

const soReusePort = 15 // SO_REUSEPORT on Linux

func listenWithReusePort(network, addr string) (net.Listener, error) {
	lc := &net.ListenConfig{
		Control: func(network, address string, c syscall.RawConn) error {
			return c.Control(func(fd uintptr) {
				syscall.SetsockoptInt(int(fd), syscall.SOL_SOCKET, soReusePort, 1)
			})
		},
	}
	return lc.Listen(context.Background(), network, addr)
}

func runServer(config *Config) error {
	fmt.Fprintf(os.Stderr, "miniserve v%s\n", VERSION)

	if config.Verbose {
		fmt.Fprintf(os.Stderr, "%s [INFO] starting 20 workers\n", logTimestamp())
	}

	handler := &miniserveHandler{config: config}
	var mainHandler http.Handler = handler
	if config.Verbose {
		mainHandler = loggingHandler(mainHandler, config)
	}

	addrs := getListenAddrs(config)
	var listeners []net.Listener

	for idx, addr := range addrs {
		// Determine network type
		network := "tcp"
		if strings.HasPrefix(addr, "[::"):
			network = "tcp6"
		} else {
			network = "tcp4"
		}

		l, err := listenWithReusePort(network, addr)
		if err != nil {
			ts := logTimestamp()
			bindTarget := addrs[0] // Use first addr for error
			if idx == 0 {
				bindTarget = addr
			}
			fmt.Fprintf(os.Stderr, "%s [ERROR] Failed to bind server to %s\n", ts, bindTarget)
			fmt.Fprintf(os.Stderr, "%s [ERROR] caused by: Address already in use (os error 98)\n", ts)
			fmt.Fprintf(os.Stderr, "Error: Failed to bind server to %s\ncaused by: Address already in use (os error 98)\n", bindTarget)
			for _, ll := range listeners {
				ll.Close()
			}
			return err
		}
		listeners = append(listeners, l)
	}

	// Print binding info
	bindStr := strings.Join(addrs, ", ")
	fmt.Fprintf(os.Stderr, "Bound to %s\n", bindStr)
	fmt.Fprintf(os.Stderr, "Serving path %s\n", config.Path)

	fmt.Fprintln(os.Stderr, "Available at (non-exhaustive list):")
	prefix := config.RoutePrefix
	for _, ip := range getLocalIPs() {
		fmt.Fprintf(os.Stderr, "    http://%s:%d%s\n", ip, config.Port, prefix)
	}
	fmt.Fprintln(os.Stderr)

	if config.Verbose {
		fmt.Fprintf(os.Stderr, "%s [INFO] Actix runtime found; starting in Actix runtime\n", logTimestamp())
		for _, addr := range addrs {
			fmt.Fprintf(os.Stderr, "%s [INFO] starting service: \"actix-web-service-%s\", workers: 20, listening on: %s\n",
				logTimestamp(), addr, addr)
		}
	}

	var tlsConfig *tls.Config
	if config.TlsCert != "" && config.TlsKey != "" {
		cert, err := tls.LoadX509KeyPair(config.TlsCert, config.TlsKey)
		if err != nil {
			return fmt.Errorf("failed to load TLS certificate: %v", err)
		}
		tlsConfig = &tls.Config{Certificates: []tls.Certificate{cert}}
	}

	servers := make([]*http.Server, len(listeners))
	for i, l := range listeners {
		srv := &http.Server{Handler: mainHandler}
		servers[i] = srv
		go func(srv *http.Server, l net.Listener) {
			var err error
			if tlsConfig != nil {
				srv.TLSConfig = tlsConfig
				err = srv.Serve(tls.NewListener(l, tlsConfig))
			} else {
				err = srv.Serve(l)
			}
			if err != nil && err != http.ErrServerClosed {
				fmt.Fprintf(os.Stderr, "Server error: %v\n", err)
			}
		}(srv, l)
	}

	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)
	sig := <-sigCh

	if config.Verbose {
		sigName := "SIGTERM"
		if sig == syscall.SIGINT {
			sigName = "SIGINT"
		}
		fmt.Fprintf(os.Stderr, "%s [INFO] %s received; starting graceful shutdown\n", logTimestamp(), sigName)
		fmt.Fprintf(os.Stderr, "%s [INFO] accept thread stopped\n", logTimestamp())
	}

	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	for _, srv := range servers {
		srv.Shutdown(ctx)
	}

	if config.Verbose {
		for i := 0; i < 20; i++ {
			fmt.Fprintf(os.Stderr, "%s [INFO] shutting down idle worker\n", logTimestamp())
		}
	}

	return nil
}

func getListenAddrs(config *Config) []string {
	port := config.Port
	if len(config.Interfaces) == 0 {
		return []string{
			fmt.Sprintf("[::]:%d", port),
			fmt.Sprintf("0.0.0.0:%d", port),
		}
	}
	var addrs []string
	for _, iface := range config.Interfaces {
		if strings.Contains(iface, ":") && !strings.HasPrefix(iface, "[") {
			addrs = append(addrs, fmt.Sprintf("[%s]:%d", iface, port))
		} else {
			addrs = append(addrs, fmt.Sprintf("%s:%d", iface, port))
		}
	}
	return addrs
}

func getLocalIPs() []string {
	var ips []string
	ifaces, err := net.Interfaces()
	if err == nil {
		for _, iface := range ifaces {
			if iface.Flags&net.FlagUp == 0 {
				continue
			}
			addrs, err := iface.Addrs()
