				var ip net.IP
				switch v := addr.(type) {
				case *net.IPNet:
					ip = v.IP
				case *net.IPAddr:
					ip = v.IP
				}
				if ip == nil || ip.IsLoopback() {
					continue
				}
				if ip4 := ip.To4(); ip4 != nil {
					ips = append(ips, ip4.String())
				}
			}
		}
	}
	result := []string{"127.0.0.1"}
	result = append(result, ips...)
	result = append(result, "[::1]")
	return result
}

func loggingHandler(next http.Handler, config *Config) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		rw := &responseWriter{ResponseWriter: w, status: 200}
		next.ServeHTTP(rw, r)
		duration := time.Since(start)

		clientIP := r.RemoteAddr
		if idx := strings.LastIndex(clientIP, ":"); idx >= 0 {
			clientIP = strings.Trim(clientIP[:idx], "[]")
		}
		ua := r.Header.Get("User-Agent")
		referer := r.Header.Get("Referer")
		if referer == "" {
			referer = "-"
		}
		fmt.Fprintf(os.Stderr, "%s [INFO] %s \"%s %s HTTP/%d.%d\" %d %d %q %q %.6f\n",
			logTimestamp(), clientIP, r.Method, r.RequestURI,
			r.ProtoMajor, r.ProtoMinor,
			rw.status, rw.size,
			referer, ua, duration.Seconds())
	})
}

type responseWriter struct {
	http.ResponseWriter
	status int
	size   int
}

func (rw *responseWriter) WriteHeader(status int) {
	rw.status = status
	rw.ResponseWriter.WriteHeader(status)
}

func (rw *responseWriter) Write(b []byte) (int, error) {
	n, err := rw.ResponseWriter.Write(b)
	rw.size += n
	return n, err
}
